INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-claude-code-intro', 'youtube', 'https://www.youtube.com/watch?v=AJpK3YTTKZ4', 'https://www.youtube.com/watch?v=AJpK3YTTKZ4', 'AJpK3YTTKZ4', 'Introducing Claude Code', 'Anthropic', NULL, 240, 'https://i.ytimg.com/vi/AJpK3YTTKZ4/hqdefault.jpg', '["common"]', '["claude-code"]', 'beginner', 'en', '["ru","en"]', '[{"day":1,"track":"common"}]', 'published', 'not_applicable', 'ready', 1, 24, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-claude-code-intro', 'ru', 'ready', '{"title":"Claude Code за четыре минуты: как выглядит работа с агентом","hook":"Короткое официальное видео от Anthropic: за четыре минуты увидишь, что такое ИИ-агент и почему мы будем работать с ним все 66 дней.","summary":"Это короткий ролик от Anthropic, где Claude Code показывают в деле. Агент работает прямо в терминале: читает файлы проекта, предлагает изменения, правит код и запускает команды, а человек ставит задачу словами и подтверждает действия.\n\nВидео на английском, но речи там немного, и почти всё понятно по экрану. Если хочешь подстраховаться, включи в YouTube субтитры и автоперевод на русский или открой ролик в Яндекс Браузере с закадровым переводом.\n\nСмотри его не как рекламу, а как карту: заметь, кто что делает. Ты формулируешь цель и проверяешь результат, агент выполняет рутину. Именно так ты будешь строить свои приложения и видео дальше.","takeaways":["Claude Code — это агент: он не просто отвечает текстом, а сам читает проект, меняет файлы и запускает команды.","Работает он в терминале — текстовом окне, куда вводят команды. Бояться его не нужно: команды в основном набирает агент.","Твоя роль — ясно описать задачу, следить за ходом работы и проверять результат.","Перед изменениями и командами агент спрашивает разрешения, и ты всегда можешь сказать «нет» или поправить план."],"steps":[{"title":"Посмотри видео целиком","detail":"Всего около четырёх минут. Если английский на слух сложен, включи субтитры → Автоперевод → Русский или закадровый перевод в Яндекс Браузере."},{"title":"Посмотри второй раз и следи за экраном","detail":"Отметь для себя три момента: как человек ставит задачу, что агент делает сам и где он просит подтверждения."},{"title":"Запиши, что тебе показалось магией","detail":"Одна-две фразы: что удивило или осталось непонятным. К этим вопросам вернёмся, когда установишь агента."},{"title":"Придумай первую задачу для агента","detail":"Что-то маленькое и личное: страница-визитка, список любимых фильмов, таймер для тренировок. Запиши её одной фразой, как будто объясняешь другу."}],"exercise":{"title":"Мой первый запрос к агенту","goal":"Сформулировать реальную маленькую задачу так, чтобы её мог выполнить ИИ-агент.","instructions":["Посмотри видео и выпиши три действия, которые агент сделал сам.","Придумай свой маленький проект на один вечер: одна веб-страница или небольшой инструмент.","Напиши запрос к агенту в 3–5 предложениях: что сделать, для кого, как должно выглядеть, как понять, что готово.","Сохрани текст — он пригодится, когда установишь Claude Code."],"proof":"text","estMinutes":20},"quiz":[{"q":"Чем ИИ-агент отличается от обычного чат-бота?","options":["Он отвечает быстрее","Он сам читает и меняет файлы проекта и запускает команды","Он работает только с картинками","Он не требует интернета"],"answer":1,"explain":"Главное отличие — агент действует: читает код, правит файлы, выполняет команды, а не только пишет ответ."},{"q":"Где в основном работает Claude Code в этом видео?","options":["В терминале","В Telegram","В Excel","В редакторе фото"],"answer":0,"explain":"Claude Code изначально работает в терминале, хотя сейчас есть и другие варианты запуска."},{"q":"Какая роль остаётся за человеком?","options":["Набирать весь код вручную","Ничего, агент всё решает сам","Ставить ясную задачу и проверять результат","Только оплачивать подписку"],"answer":2,"explain":"Ты отвечаешь за цель и качество: формулируешь задачу, подтверждаешь действия и проверяешь, что получилось."}],"suggestedDays":[{"day":1,"track":"common","reason":""}],"tracks":["common"],"topics":["claude-code"],"tags":["claude code","агенты","терминал","первый шаг"],"level":"beginner","estMinutes":25}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-claude-code-intro');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-claude-code-intro', 'en', 'ready', '{"title":"Introducing Claude Code: a 4-minute first look","hook":"Four minutes that show you what an AI coding agent actually does, so the rest of the program makes sense.","summary":"This short launch video from Anthropic shows Claude Code working inside a terminal. Instead of chatting in a browser and copying code back and forth, you describe what you want in plain language and the agent reads the project, proposes changes to files, runs commands and reports back.\n\nYou do not need to understand every line on screen. Watch for the shape of the loop: a person asks for something, the agent explores and plans, it asks permission before changing things, and the person reviews the result. That loop is the core skill you will practise for the next 66 days.\n\nThe video was made for an earlier release, so the interface you install today may look a little different. The idea has not changed.","takeaways":["Claude Code is an agent: it can read files, edit them and run commands, not just answer questions.","You talk to it in plain language; being clear about the goal matters more than knowing syntax.","It asks for permission before acting, and you stay in charge of what gets accepted.","Your job shifts from typing code to describing, reviewing and testing."],"steps":[{"title":"Watch the whole video once","detail":"Just watch. Do not take notes yet; get a feel for how the conversation with the agent flows."},{"title":"Watch again and pause at each request","detail":"Each time the person types a request, pause and say out loud what they asked for and what the agent did in response."},{"title":"Spot the permission moments","detail":"Notice when the agent stops to ask before editing a file or running a command. This is your safety net later."},{"title":"Write down three things you want to build","detail":"Small and concrete: a page about your hobby, a tool that tracks your water intake, a short animated title for a video."}],"exercise":{"title":"My first three agent requests","goal":"Turn vague ideas into clear requests you could give an agent tomorrow.","instructions":["Pick three small things you would like to exist (a web page, a tiny tool, a short video).","For each one, write a request of 3–5 sentences: what it is, who it is for, what it should look like, and how you will know it works.","Under each request, write one question you think the agent might ask you back.","Paste all three into your journal for today."],"proof":"text","estMinutes":20},"quiz":[{"q":"What makes Claude Code different from a regular chatbot?","options":["It only works offline","It can read and edit files and run commands in your project","It writes code but cannot explain it","It replaces the need to review anything"],"answer":1,"explain":"An agent acts inside your project: it reads, edits and runs things, with your permission."},{"q":"What is your main job when working with a coding agent?","options":["Typing every line of code yourself","Memorising programming syntax first","Avoiding giving it any context","Describing the goal clearly and reviewing what it does"],"answer":3,"explain":"Clear goals plus careful review is the core loop of this program."},{"q":"Why does the agent ask for permission before some actions?","options":["Because it is broken","So you stay in control of changes to your files and system","To slow you down on purpose","It never asks"],"answer":1,"explain":"Permission prompts let you check edits and commands before they happen."}],"suggestedDays":[{"day":1,"track":"common","reason":""}],"tracks":["common"],"topics":["claude-code"],"tags":["claude-code","intro","agents","terminal"],"level":"beginner","estMinutes":25}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-claude-code-intro');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-claude-code-intro', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-claude-code-intro') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-claude-code-intro');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-mastering-claude-code', 'youtube', 'https://www.youtube.com/watch?v=6eBSHbLKuN0', 'https://www.youtube.com/watch?v=6eBSHbLKuN0', '6eBSHbLKuN0', 'Mastering Claude Code in 30 minutes', 'Anthropic', NULL, 1680, 'https://i.ytimg.com/vi/6eBSHbLKuN0/hqdefault.jpg', '["common"]', '["claude-code","workflow"]', 'beginner', 'en', '["ru","en"]', '[{"day":4,"track":"common"}]', 'published', 'not_applicable', 'ready', 1, 23, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-mastering-claude-code', 'ru', 'ready', '{"title":"Claude Code на полную: практические приёмы за 30 минут","hook":"Доклад от Anthropic о том, как работать с Claude Code продуктивно: настройка, контекст проекта и приёмы, которые экономят часы.","summary":"Это получасовой доклад с конференции Anthropic о том, как пользоваться Claude Code каждый день. Говорят о настройке, о том, как дать агенту контекст проекта (в том числе через файл CLAUDE.md), как управлять разрешениями и как строить работу так, чтобы агент реже ошибался.\n\nВидео на английском, темп довольно быстрый. Включи субтитры с автопереводом или закадровый перевод в Яндекс Браузере, а если что-то непонятно, ставь на паузу и пробуй сразу у себя в терминале.\n\nНе пытайся запомнить всё. Твоя задача сегодня — выписать два-три приёма и применить их на своём проекте. Остальное вернётся само, когда будешь работать с агентом каждый день.","takeaways":["Агенту нужен контекст: чем лучше он понимает проект и твои правила, тем точнее работает.","CLAUDE.md — файл в корне проекта с инструкциями для агента. Claude Code читает его в начале каждой сессии.","Сначала попроси агента изучить код и предложить план, а уже потом писать код — так меньше переделок.","Разрешения можно настроить: что агент делает сам, а на что спрашивает подтверждение.","Лучшие результаты получаются в коротком цикле: маленькая задача → проверка → следующая."],"steps":[{"title":"Посмотри доклад с субтитрами","detail":"Около получаса. Держи рядом заметки и выписывай приёмы, которые хочется попробовать."},{"title":"Открой свой проект в Claude Code","detail":"Перейди в папку проекта в терминале и запусти claude. Если проекта нет, создай пустую папку — для упражнения этого хватит."},{"title":"Попроси агента рассказать о проекте","detail":"Напиши: «Изучи этот проект и объясни простыми словами, что в нём есть». Так ты увидишь, как агент собирает контекст."},{"title":"Создай CLAUDE.md","detail":"Команда /init попросит агента составить черновик CLAUDE.md. Прочитай его и допиши свои правила: например, «отвечай по-русски», «объясняй каждую команду»."},{"title":"Попробуй режим «сначала план»","detail":"Дай небольшую задачу и попроси сначала план без изменений файлов. Обсуди план, а потом разреши выполнять."}],"exercise":{"title":"Свой CLAUDE.md и одна задача по плану","goal":"Настроить агента под себя и выполнить одну маленькую задачу через цикл «план → код → проверка».","instructions":["В папке проекта запусти Claude Code и выполни /init.","Допиши в CLAUDE.md минимум три своих правила (язык ответов, стиль, что проверять перед завершением).","Дай агенту маленькую задачу и попроси сначала план, без правок файлов.","Утверди план, дождись результата и проверь его сам.","Сохрани итоговый CLAUDE.md и коротко опиши, что изменилось в ответах агента."],"proof":"file","estMinutes":45},"quiz":[{"q":"Зачем нужен файл CLAUDE.md?","options":["Это лицензия проекта","Это инструкции и контекст для агента, которые он читает в начале сессии","Это журнал ошибок","Это файл с паролями"],"answer":1,"explain":"В CLAUDE.md пишут, как устроен проект и по каким правилам работать, чтобы не повторять это каждый раз."},{"q":"Почему полезно сначала попросить план?","options":["Так агент работает бесплатно","План заменяет тестирование","Без плана агент не запустится","Можно поймать неверное понимание задачи до того, как агент напишет много кода"],"answer":3,"explain":"Поправить план дешевле, чем переделывать готовый код."},{"q":"Какой ритм работы с агентом самый надёжный?","options":["Короткие циклы: маленькая задача, проверка, следующая","Одна огромная задача на весь день","Никогда не проверять результат","Менять задачу каждые пять минут"],"answer":0,"explain":"Маленькие шаги легко проверить и легко откатить, если что-то пошло не так."}],"suggestedDays":[{"day":4,"track":"common","reason":"Агент уже установлен — пора научиться работать с ним правильно с самого начала."}],"tracks":["common"],"topics":["claude-code","workflow"],"tags":["claude code","claude.md","рабочий процесс","контекст"],"level":"beginner","estMinutes":75}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-mastering-claude-code');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-mastering-claude-code', 'en', 'ready', '{"title":"Mastering Claude Code in 30 minutes","hook":"A talk from the team behind Claude Code on how they actually use it day to day.","summary":"This is a talk from Anthropic about getting real work done with Claude Code. It covers setting it up, giving it the right context, and the everyday habits that separate frustrating sessions from productive ones.\n\nSome parts assume you already write code, so do not worry if a few examples go over your head. Focus on the habits: asking the agent questions about a project before changing it, asking it to make a plan first, keeping project notes in a CLAUDE.md file so it remembers your preferences, and stopping it early when it heads in the wrong direction.\n\nFeatures and shortcuts change between versions. If something in the talk does not match your screen, check the current Claude Code docs; the working habits are what you are here for.","takeaways":["Start by asking the agent to explain the project before you ask it to change anything.","Ask for a plan first, read it, then let it build. Planning saves time on anything bigger than a one-line fix.","A CLAUDE.md file in your project is a place for standing instructions the agent reads every session.","Interrupt early when it goes off track; redirecting is cheaper than undoing.","Give it a way to check its own work, such as running the app or a test."],"steps":[{"title":"Watch with a notes file open","detail":"Every time a habit or tip is mentioned, write one line about it in your own words."},{"title":"Circle three habits you can use this week","detail":"Pick the ones that make sense for a beginner: explain-first, plan-first, and CLAUDE.md are good candidates."},{"title":"Create a practice folder","detail":"Make an empty folder, open a terminal in it, and start Claude Code there."},{"title":"Try explain, then plan, then build","detail":"Ask Claude to create a one-page website about a topic you love, but first tell it: ''Make a plan and wait for my OK before writing files.'' Read the plan, adjust it, then approve."},{"title":"Ask it to write a CLAUDE.md","detail":"Tell it your preferences (for example: explain changes in simple words, keep things in plain HTML) and ask it to save them in CLAUDE.md."}],"exercise":{"title":"Plan first, then build","goal":"Experience the plan-then-build loop and leave a CLAUDE.md behind for future sessions.","instructions":["In a new folder, start Claude Code and ask for a plan for a single-page site about something you care about. Ask it not to write files yet.","Reply with at least one change to the plan (a section to add, a colour, a tone).","Approve the plan and let it build. Open the page in your browser.","Ask Claude to create a CLAUDE.md with three preferences you want it to follow from now on.","Paste the final plan and your CLAUDE.md contents into your journal."],"proof":"text","estMinutes":45},"quiz":[{"q":"Before asking the agent to change an unfamiliar project, what is a good first move?","options":["Ask it to explain how the project is organised","Ask it to rewrite everything","Delete files you do not understand","Turn off all permission prompts"],"answer":0,"explain":"Understanding first leads to better requests and fewer surprises."},{"q":"What is CLAUDE.md used for?","options":["Storing your passwords","A log of every command ever run","Standing instructions and project notes the agent reads each session","A backup of your code"],"answer":2,"explain":"It is a memory file for preferences, commands and conventions."},{"q":"The agent starts doing something you did not want. What should you do?","options":["Interrupt it and redirect with a clearer instruction","Wait until it finishes, then delete everything","Close the laptop","Start a new project"],"answer":0,"explain":"Stopping early and correcting course is much cheaper than undoing later."},{"q":"Why ask for a plan before code on a bigger task?","options":["Plans are required by law","It makes the agent faster at typing","You can catch misunderstandings before any files change","Plans replace testing"],"answer":2,"explain":"Reading a plan is the cheapest moment to fix a wrong assumption."}],"suggestedDays":[{"day":4,"track":"common","reason":"Right after your first install: learn good habits before bad ones form."}],"tracks":["common"],"topics":["claude-code","workflow"],"tags":["claude-code","workflow","claude-md","planning"],"level":"beginner","estMinutes":75}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-mastering-claude-code');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-mastering-claude-code', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-mastering-claude-code') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-mastering-claude-code');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-karpathy-intro-llm', 'youtube', 'https://www.youtube.com/watch?v=zjkBMFhNj_g', 'https://www.youtube.com/watch?v=zjkBMFhNj_g', 'zjkBMFhNj_g', '[1hr Talk] Intro to Large Language Models', 'Andrej Karpathy', NULL, 3588, 'https://i.ytimg.com/vi/zjkBMFhNj_g/hqdefault.jpg', '["common"]', '["llm-basics"]', 'beginner', 'en', '["ru","en"]', '[{"day":9,"track":"common"}]', 'published', 'not_applicable', 'ready', 1, 22, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-karpathy-intro-llm', 'ru', 'ready', '{"title":"Что такое большие языковые модели: лекция Андрея Карпаты","hook":"Лучшее часовое введение в LLM для неспециалиста: откуда берутся модели вроде ChatGPT и Claude, что они умеют и где их слабые места.","summary":"Андрей Карпаты — один из самых известных исследователей ИИ, работал в OpenAI и Tesla. В этой часовой лекции он без формул объясняет, что такое большая языковая модель: по сути это файл с миллиардами чисел-параметров и небольшая программа, которая их запускает. Модель учится предсказывать следующий кусочек текста на огромном объёме данных из интернета, а потом её дообучают быть полезным ассистентом.\n\nДальше он говорит о том, куда всё движется: модели пользуются инструментами (поиск, калькулятор, код), LLM становится похожа на ядро новой операционной системы. В конце — про безопасность: джейлбрейки, prompt injection (когда вредная инструкция спрятана в тексте, который читает модель) и отравление данных.\n\nЛекция на английском, но Карпаты говорит спокойно и рисует понятные слайды. Включи автоперевод субтитров или закадровый перевод в Яндекс Браузере. На русском её тоже пересказывали — можно поискать конспекты на Хабре, но оригинал стоит посмотреть самому.","takeaways":["LLM учится предсказывать следующий токен (кусочек текста) — из этой простой задачи вырастают удивительные способности.","Обучение идёт в два этапа: предобучение на огромном объёме текста и дообучение, которое делает из модели ассистента.","Модель может уверенно ошибаться (галлюцинировать) — проверять её ответы нужно всегда.","Современные модели пользуются инструментами, и именно это превращает их в агентов.","У LLM свои уязвимости: джейлбрейки и prompt injection — это реальные риски, а не фантастика."],"steps":[{"title":"Включи перевод и смотри по частям","detail":"Час — это много для первого дня. Раздели на два-три подхода по 20 минут, используя главы в описании видео."},{"title":"Веди конспект из пяти пунктов","detail":"После каждой части запиши одну главную мысль своими словами. Если не получается объяснить просто — пересмотри кусок."},{"title":"Проверь понимание с ассистентом","detail":"Открой Claude или другой чат-ассистент и попроси: «Задай мне 5 вопросов по основам LLM и проверь мои ответы». Отвечай сам, без подглядывания."},{"title":"Найди одну галлюцинацию","detail":"Спроси модель о чём-то узком, что хорошо знаешь сам (о своём городе, хобби, работе). Поищи неточности — так ощущение «модель может ошибаться» станет личным опытом."}],"exercise":{"title":"Объясни LLM бабушке","goal":"Проверить, что ты понял базовые идеи настолько, чтобы рассказать их человеку без технического фона.","instructions":["Посмотри лекцию хотя бы до части про безопасность.","Напиши объяснение на 150–250 слов: что такое LLM, как её учат, почему она может ошибаться.","Без терминов без пояснений: каждое умное слово объясни в скобках.","Попроси Claude найти неточности в твоём тексте и исправь их сам."],"proof":"text","estMinutes":30},"quiz":[{"q":"Какую задачу решает языковая модель на этапе предобучения?","options":["Ищет ответы в базе данных","Переводит тексты с английского","Предсказывает следующий кусочек текста","Запоминает пароли пользователей"],"answer":2,"explain":"Модель учат предсказывать следующий токен на огромном корпусе текстов."},{"q":"Что делает дообучение после предобучения?","options":["Превращает модель в полезного ассистента, отвечающего на вопросы","Удаляет из модели все знания","Уменьшает размер файла в десять раз","Подключает модель к интернету"],"answer":0,"explain":"На этапе дообучения модель учат вести диалог и помогать, на примерах хороших ответов."},{"q":"Что такое prompt injection?","options":["Ускорение модели","Способ сделать промпт короче","Новая версия модели","Вредная инструкция, спрятанная в тексте, который читает модель"],"answer":3,"explain":"Например, на веб-странице спрятан текст «игнорируй прошлые указания» — и модель может ему последовать."},{"q":"Почему ответы модели нужно проверять?","options":["Модель всегда отвечает неправильно","Модель может уверенно выдумывать факты","Проверять не нужно","Модель отвечает только на английском"],"answer":1,"explain":"Галлюцинации звучат так же уверенно, как правда, поэтому проверка — твоя обязанность."}],"suggestedDays":[{"day":9,"track":"common","reason":""}],"tracks":["common"],"topics":["llm-basics"],"tags":["llm","карпаты","основы ии","безопасность"],"level":"beginner","estMinutes":95}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-karpathy-intro-llm');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-karpathy-intro-llm', 'en', 'ready', '{"title":"Intro to Large Language Models (Andrej Karpathy, 1 hour)","hook":"The clearest one-hour explanation of what is inside ChatGPT and Claude, from someone who helped build them.","summary":"Andrej Karpathy explains large language models for a general audience. He starts from the fact that a model is essentially a big file of learned numbers plus a small program to run it, then explains how that file is made: first by training on a huge amount of internet text to predict the next word, then by fine-tuning on example conversations so it behaves like a helpful assistant.\n\nThe second part looks at where things are heading: models that use tools like a browser or calculator, that work with images and audio, and the idea of the LLM as the core of a new kind of operating system. The final part covers security problems such as jailbreaks and prompt injection.\n\nYou do not need maths for this. If you only have time for part of it today, watch the first half (how models are trained and why they sometimes make things up) and come back to the rest.","takeaways":["A language model is trained to predict the next piece of text; everything else grows out of that.","Pre-training on lots of text gives knowledge; fine-tuning on conversations turns it into an assistant.","Models can confidently produce wrong answers, so checking their output is part of the job.","Models get far more useful when they can use tools, which is exactly what coding agents do.","Prompt injection and jailbreaks are real risks whenever a model reads untrusted text."],"steps":[{"title":"Watch the first half with notes","detail":"Write down, in your own words, the two training stages and what each one adds."},{"title":"Explain it to someone in two minutes","detail":"Out loud or in writing, explain to a friend how a model learns. If you get stuck, rewatch that part."},{"title":"Test the next-word idea yourself","detail":"Ask an AI assistant to continue an unfinished sentence in three different ways and notice how it picks likely continuations."},{"title":"Catch a confident mistake","detail":"Ask an assistant about a very obscure local fact you know well. Note whether it admits uncertainty or invents details."},{"title":"Skim the security section","detail":"Watch the last part on jailbreaks and prompt injection; note one example you understood."}],"exercise":{"title":"My one-page LLM explainer","goal":"Prove to yourself you understand the basics by explaining them simply.","instructions":["Write a short explainer (150–250 words) titled ''How an AI model learns'', aimed at a curious 12-year-old.","Cover: next-word prediction, the two training stages, and why the model can be wrong.","Add one real example from your own test where an assistant was wrong or unsure.","Save it in your journal. You will reuse it on your first web page later."],"proof":"text","estMinutes":30},"quiz":[{"q":"At its core, what is a large language model trained to do?","options":["Search the internet live","Store a copy of every website","Run code on your computer","Predict the next piece of text"],"answer":3,"explain":"Next-token prediction is the base task everything else builds on."},{"q":"What does fine-tuning on example conversations add?","options":["More general knowledge from the web","Assistant-like behaviour: answering questions helpfully","The ability to see images","Faster hardware"],"answer":1,"explain":"Pre-training gives knowledge; fine-tuning shapes it into a helpful assistant."},{"q":"Why should you double-check an LLM''s factual answers?","options":["Because it never knows anything","Because it always refuses","You should not; it is always correct","Because it can produce fluent, confident text that is wrong"],"answer":3,"explain":"Fluent does not mean true; models can make things up."},{"q":"What is prompt injection?","options":["Typing very long prompts","Hidden instructions in content the model reads that try to hijack its behaviour","A way to speed up training","A billing feature"],"answer":1,"explain":"Untrusted text can contain instructions the model might follow."}],"suggestedDays":[{"day":9,"track":"common","reason":""}],"tracks":["common"],"topics":["llm-basics"],"tags":["llm","karpathy","fundamentals","security"],"level":"beginner","estMinutes":95}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-karpathy-intro-llm');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-karpathy-intro-llm', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-karpathy-intro-llm') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-karpathy-intro-llm');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-3b1b-gpt', 'youtube', 'https://www.youtube.com/watch?v=wjZofJX0v4M', 'https://www.youtube.com/watch?v=wjZofJX0v4M', 'wjZofJX0v4M', 'But what is a GPT? Visual intro to transformers | Chapter 5, Deep Learning', '3Blue1Brown', NULL, 1620, 'https://i.ytimg.com/vi/wjZofJX0v4M/hqdefault.jpg', '["common"]', '["llm-basics"]', 'intermediate', 'en', '["ru","en"]', '[{"day":7,"track":"common"}]', 'published', 'not_applicable', 'ready', 0, 21, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-3b1b-gpt', 'ru', 'ready', '{"title":"Как устроен GPT: наглядно о трансформерах от 3Blue1Brown","hook":"Самое красивое визуальное объяснение того, что происходит внутри GPT: токены, векторы и как модель выбирает следующее слово.","summary":"3Blue1Brown — канал Гранта Сандерсона, знаменитый анимациями, которые делают математику понятной. Это пятая глава его серии о глубоком обучении, и она про трансформеры — архитектуру, на которой построены GPT, Claude и другие современные модели.\n\nГрант показывает путь текста через модель: текст режется на токены, каждый превращается в вектор — длинный список чисел, где направления в пространстве несут смысл. Потом блоки внимания (attention) позволяют словам «учитывать» друг друга, а в конце модель выдаёт вероятности для следующего токена и выбирает один. Там же объясняется, что такое температура и почему ответы бывают разными.\n\nВидео на английском и местами математичное — это нормально, если не всё будет понятно с первого раза. Включи автоперевод субтитров или закадровый перевод в Яндекс Браузере. На русском есть озвучки серии от энтузиастов — можно поискать на YouTube, но проверяй, что это та самая глава.","takeaways":["Текст для модели — это последовательность токенов, а не слов и не букв.","Каждый токен становится вектором; близкие по смыслу слова оказываются рядом в этом пространстве.","Внимание (attention) позволяет каждому токену учитывать контекст вокруг.","На выходе модель даёт вероятности следующего токена, а температура влияет на то, насколько смело она выбирает.","Понимать математику до конца не обязательно — важно понять общий конвейер."],"steps":[{"title":"Смотри с паузами","detail":"Около 27 минут, но плотных. Останавливайся после каждой новой идеи и проговаривай её своими словами."},{"title":"Нарисуй схему конвейера","detail":"На бумаге: текст → токены → векторы → внимание → вероятности → следующий токен. Пять-шесть прямоугольников со стрелками."},{"title":"Посмотри на токены своими глазами","detail":"Попроси Claude: «Объясни, на какие примерно токены разобьётся фраза на русском и на английском и почему русский текст обычно занимает больше токенов»."},{"title":"Поиграй с температурой","detail":"Попроси ассистента написать три разных варианта одной фразы — и посмотри, как меняются ответы. Это и есть случайность выбора следующего токена."}],"exercise":{"title":"Схема «как GPT пишет следующее слово»","goal":"Собрать свою наглядную схему работы трансформера, которую сможешь объяснить другому.","instructions":["Посмотри видео целиком.","Нарисуй схему конвейера от текста до следующего токена (бумага, Excalidraw или любой редактор).","Под каждым блоком подпиши одну фразу: что там происходит.","Сфотографируй или сохрани схему как картинку."],"proof":"file","estMinutes":25},"quiz":[{"q":"Что такое токен?","options":["Пароль для доступа к модели","Всегда одно целое слово","Кусочек текста, с которым работает модель","Одна буква"],"answer":2,"explain":"Токен может быть словом, частью слова или знаком — модель видит текст как последовательность токенов."},{"q":"Зачем токены превращают в векторы?","options":["Чтобы модель могла работать со смыслом через числа","Чтобы сжать текст для отправки","Чтобы зашифровать данные","Чтобы перевести текст на английский"],"answer":0,"explain":"Нейросеть работает с числами, а в векторах направления и расстояния отражают смысл."},{"q":"Что делает механизм внимания (attention)?","options":["Следит за пользователем","Позволяет токенам учитывать контекст других токенов","Удаляет лишние слова","Ускоряет интернет"],"answer":1,"explain":"Благодаря вниманию значение слова уточняется с учётом окружающего текста."}],"suggestedDays":[{"day":7,"track":"common","reason":""}],"tracks":["common"],"topics":["llm-basics"],"tags":["трансформеры","токены","визуализация","llm"],"level":"intermediate","estMinutes":55}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-3b1b-gpt');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-3b1b-gpt', 'en', 'ready', '{"title":"But what is a GPT? A visual intro to transformers (3Blue1Brown)","hook":"Beautiful animations that let you see how text becomes numbers and numbers become the next word.","summary":"Grant Sanderson of 3Blue1Brown walks through what happens inside a GPT-style model, using his trademark animations. Text is split into small pieces called tokens, each token is turned into a long list of numbers (an embedding), and those lists flow through repeated layers, mainly attention blocks and simple feed-forward blocks, until the model produces a probability for every possible next token.\n\nA memorable idea is that directions in this space of numbers can carry meaning, so related words end up near each other. He also explains how the final probabilities are produced and how a setting called temperature makes the output more predictable or more varied.\n\nThis is part of a deep learning series and is a step up from the Karpathy intro. Some maths appears, but you can follow the story without it. Watch for the big picture, not the formulas.","takeaways":["Models do not see words; they see tokens, small chunks of text turned into lists of numbers.","Embeddings place tokens in a space where direction and distance can carry meaning.","Attention lets each token take information from the other tokens around it.","The output is a probability for every possible next token; temperature controls how adventurous the pick is.","The context window is how much text the model can consider at once."],"steps":[{"title":"Watch without pausing for maths","detail":"Let the formulas wash over you. Track the journey: text, tokens, numbers, layers, next-word probabilities."},{"title":"Draw the pipeline","detail":"On paper, draw five boxes from left to right for that journey and label each in your own words."},{"title":"See tokens for real","detail":"Search for a free online tokenizer tool from a model provider and paste in a sentence. Notice how words get split."},{"title":"Play with temperature","detail":"If you have access to a model playground, ask the same question at low and high temperature and compare the answers."}],"exercise":{"title":"Sketch the GPT pipeline","goal":"Create a diagram you could use to explain a transformer to a friend.","instructions":["Draw (on paper or in any drawing app) the path from a sentence to a predicted next word.","Include these labels: tokens, embeddings, attention, probabilities, temperature.","Write one plain sentence under each label explaining it.","Take a photo or screenshot and upload it."],"proof":"file","estMinutes":30},"quiz":[{"q":"What is a token?","options":["A password for the API","A full paragraph","A small chunk of text the model works with","A type of GPU"],"answer":2,"explain":"Text is split into tokens, which may be whole words or parts of words."},{"q":"What does the attention mechanism let a token do?","options":["Take in information from other tokens in the context","Skip the rest of the text","Choose its own temperature","Delete earlier tokens"],"answer":0,"explain":"Attention is how context flows between tokens."},{"q":"A higher temperature makes the model''s output...","options":["More predictable","Shorter","More varied and surprising","Always correct"],"answer":2,"explain":"Temperature flattens the probabilities so less likely words get picked more often."}],"suggestedDays":[{"day":7,"track":"common","reason":""}],"tracks":["common"],"topics":["llm-basics"],"tags":["transformers","tokens","embeddings","visual"],"level":"intermediate","estMinutes":60}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-3b1b-gpt');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-3b1b-gpt', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-3b1b-gpt') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-3b1b-gpt');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-karpathy-deep-dive', 'youtube', 'https://www.youtube.com/watch?v=7xTGNNLPyMI', 'https://www.youtube.com/watch?v=7xTGNNLPyMI', '7xTGNNLPyMI', 'Deep Dive into LLMs like ChatGPT', 'Andrej Karpathy', NULL, 12660, 'https://i.ytimg.com/vi/7xTGNNLPyMI/hqdefault.jpg', '["common"]', '["llm-basics","prompting"]', 'intermediate', 'en', '["ru","en"]', '[{"day":21,"track":"common"}]', 'published', 'not_applicable', 'ready', 0, 20, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-karpathy-deep-dive', 'ru', 'ready', '{"title":"Большое погружение в LLM от Карпаты: что смотреть сегодня","hook":"Три с половиной часа о том, как на самом деле делают ChatGPT-подобные модели. Сегодня не нужно всё — выбери главные части.","summary":"Это подробная лекция Андрея Карпаты для широкой аудитории: весь путь создания модели вроде ChatGPT. Данные из интернета и их чистка, токенизация, обучение нейросети, генерация текста, затем дообучение на диалогах, обучение с подкреплением и модели, которые «думают» перед ответом. Попутно он объясняет практичные вещи: откуда берутся галлюцинации, зачем моделям инструменты, почему модель путается в подсчёте букв.\n\nВидео длинное и на английском. Не пытайся осилить его за раз. Сегодня посмотри части про дообучение и «психологию» моделей: галлюцинации, использование инструментов, почему моделям нужны токены, чтобы рассуждать. Найди их по главам в описании или в таймлайне YouTube. Остальное можно досмотреть в выходные.\n\nДля перевода включи автосубтитры на русском или закадровый перевод в Яндекс Браузере. Эта лекция сильно прокачивает интуицию, а интуиция — главное, что нужно, чтобы хорошо писать промпты.","takeaways":["Чат-ассистент — это базовая модель, дообученная на примерах диалогов; его «характер» тоже результат обучения.","Галлюцинации — следствие того, как модель учится; инструменты вроде поиска помогают с ними бороться.","Модели нужны токены, чтобы рассуждать: просьба думать по шагам часто улучшает ответ.","Задачи на точный подсчёт и посимвольную работу модели даются плохо из-за токенизации — лучше дать им инструмент или код.","Обучение с подкреплением учит модель находить решения самой, отсюда «думающие» модели."],"steps":[{"title":"Открой список глав","detail":"В описании видео есть разметка по темам. Выбери части про post-training, галлюцинации, инструменты и «модели нужны токены, чтобы думать»."},{"title":"Смотри с переводом 60–90 минут","detail":"Субтитры → Автоперевод → Русский или Яндекс Браузер. Делай паузы и записывай примеры, которые приводит Карпаты."},{"title":"Проверь идеи на практике","detail":"Попроси модель посчитать буквы в длинном слове, затем попроси сделать то же самое с помощью кода. Сравни."},{"title":"Сформулируй правила для промптов","detail":"Из увиденного выведи три правила: например, «прошу думать по шагам», «для точных расчётов прошу код», «проверяю факты»."}],"exercise":{"title":"Три эксперимента над моделью","goal":"На практике увидеть галлюцинации, ошибки токенизации и пользу рассуждения по шагам.","instructions":["Задай модели вопрос о малоизвестном факте, который можешь проверить сам. Запиши, придумала ли она что-то.","Попроси посчитать, сколько раз буква «р» встречается в длинной фразе. Потом попроси решить это кодом.","Дай задачку на логику: сначала «ответь одним словом», потом «рассуждай по шагам». Сравни ответы.","Запиши результаты трёх экспериментов и вывод из каждого в 1–2 предложения."],"proof":"text","estMinutes":40},"quiz":[{"q":"Почему модели часто ошибаются, считая буквы в слове?","options":["Им запрещено считать","Они видят текст токенами, а не отдельными буквами","У них нет памяти","Они не знают алфавит"],"answer":1,"explain":"Слово может быть одним-двумя токенами, и отдельные буквы модель «не видит» напрямую."},{"q":"Что помогает модели лучше решать задачи, требующие рассуждений?","options":["Короткий ответ одним словом","Капслок в промпте","Возможность рассуждать по шагам перед ответом","Английский язык вместо русского"],"answer":2,"explain":"Каждый токен — это немного вычислений; рассуждение по шагам даёт модели больше «места подумать»."},{"q":"Как можно снизить риск галлюцинаций?","options":["Дать модели доступ к поиску или источникам и проверять факты","Задавать вопрос дважды подряд","Писать промпт капслоком","Галлюцинации нельзя снизить никак"],"answer":0,"explain":"Инструменты и проверка источников — основные способы борьбы с выдумками."}],"suggestedDays":[{"day":21,"track":"common","reason":""}],"tracks":["common"],"topics":["llm-basics","prompting"],"tags":["llm","карпаты","галлюцинации","токенизация","промптинг"],"level":"intermediate","estMinutes":130}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-karpathy-deep-dive');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-karpathy-deep-dive', 'en', 'ready', '{"title":"Deep Dive into LLMs like ChatGPT (Karpathy, watch in parts)","hook":"The long version: how chat models are built, why they fail in odd ways, and how to use them well.","summary":"This is a three-and-a-half-hour lecture for a general audience that goes through the whole life of a chat model: collecting and filtering internet text, splitting it into tokens, training a neural network to predict the next token, then post-training it on human-written conversations so it acts as an assistant, and finally reinforcement learning, which is how newer ''thinking'' models learn to reason step by step.\n\nAlong the way Karpathy explains practical quirks you will run into constantly: why models hallucinate, why they struggle with counting letters or spelling (tokens again), why they do better when allowed to work through a problem in steps, and why giving them information directly in the prompt beats relying on what they remember.\n\nDo not try to watch it all today. Today, watch from the start through the section on post-training and hallucinations, the first hour or so. Save reinforcement learning and the ''thinking'' models section for later in the week.","takeaways":["A chat model is a pre-trained text predictor that has been taught, with example conversations, to behave like an assistant.","Models hallucinate because they imitate confident answers; tools like web search and clear context reduce this.","Putting the facts you need into the prompt works better than relying on the model''s memory.","Models need room to think: asking for step-by-step work helps on tricky problems.","Odd failures such as miscounting letters often come from tokenization, not stupidity."],"steps":[{"title":"Plan your viewing","detail":"Split the video into three sittings across the week. Today: up to and including post-training and hallucinations."},{"title":"Keep a ''quirks'' list","detail":"Every time Karpathy mentions a weird failure mode, write it down with a one-line reason."},{"title":"Test a quirk","detail":"Ask an assistant to count a specific letter in a long word, then ask it to spell the word out letter by letter first and count again. Compare."},{"title":"Test context versus memory","detail":"Ask a question about a long text from memory, then paste the text in and ask again. Note the difference."},{"title":"Turn the quirks into prompting rules","detail":"Write three rules for yourself, such as ''give it the source text'' or ''ask it to work step by step''."}],"exercise":{"title":"My personal prompting rulebook, version 1","goal":"Turn what you learned about model quirks into rules you will actually use with your coding agent.","instructions":["List at least four quirks from the lecture in your own words.","For each, run a small test with an AI assistant and note what happened.","Write a rule that works around each quirk (for example: ''paste the error message, do not describe it'').","Save the rulebook in your journal; you will add to it all program long."],"proof":"text","estMinutes":40},"quiz":[{"q":"Why do models often struggle to count letters in a word?","options":["They cannot do any maths","They see tokens, not individual letters","The internet has no spelling data","Counting is blocked on purpose"],"answer":1,"explain":"Words are split into tokens, so individual letters are not directly visible."},{"q":"What is a reliable way to reduce made-up facts?","options":["Ask the same question louder","Use shorter words","Turn off post-training","Give the model the relevant information directly in the prompt"],"answer":3,"explain":"Information in the context is used far more reliably than vague memory."},{"q":"What does post-training on conversations change?","options":["It gives the model internet access","It makes the base model behave like a helpful assistant","It deletes its knowledge","It makes it smaller"],"answer":1,"explain":"Post-training shapes behaviour; most knowledge comes from pre-training."},{"q":"Why ask a model to work step by step on a hard problem?","options":["It costs less","It hides mistakes","Models refuse otherwise","Each token has limited computation, so spreading work over more tokens helps"],"answer":3,"explain":"Models need tokens to think; reasoning out loud gives them room."}],"suggestedDays":[{"day":21,"track":"common","reason":""}],"tracks":["common"],"topics":["llm-basics","prompting"],"tags":["llm","karpathy","hallucinations","tokenization","deep-dive"],"level":"intermediate","estMinutes":110}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-karpathy-deep-dive');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-karpathy-deep-dive', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-karpathy-deep-dive') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-karpathy-deep-dive');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-karpathy-software-3', 'youtube', 'https://www.youtube.com/watch?v=LCEmiRjPEtQ', 'https://www.youtube.com/watch?v=LCEmiRjPEtQ', 'LCEmiRjPEtQ', 'Andrej Karpathy: Software Is Changing (Again)', 'Y Combinator', NULL, 2370, 'https://i.ytimg.com/vi/LCEmiRjPEtQ/hqdefault.jpg', '["common"]', '["agents","career"]', 'beginner', 'en', '["ru","en"]', '[{"day":14,"track":"common"}]', 'published', 'not_applicable', 'ready', 0, 19, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-karpathy-software-3', 'ru', 'ready', '{"title":"Софт меняется снова: Карпаты о Software 3.0","hook":"Доклад о том, почему писать программы на естественном языке — уже реальность, и какое место в этом мире можешь занять ты.","summary":"Это выступление Андрея Карпаты на AI Startup School от Y Combinator. Он делит историю софта на три эпохи: Software 1.0 — код, который пишут люди; Software 2.0 — веса нейросетей; Software 3.0 — программы, которые пишутся промптами на обычном языке. Отсюда его мысль: программировать теперь может гораздо больше людей.\n\nДальше он разбирает, что такое LLM: и как коммунальная услуга, и как операционная система, и как «духи людей» со странными сильными и слабыми сторонами — модель может блестяще решить сложное и споткнуться на простом, и она не помнит прошлых разговоров. Поэтому лучше строить приложения с частичной автономией: ИИ делает работу, человек быстро проверяет, а «ползунок автономии» двигают постепенно. Ещё он говорит про vibe coding и про то, что софт теперь надо делать удобным и для агентов.\n\nДоклад на английском, около 40 минут. Включи автоперевод субтитров или закадровый перевод в Яндекс Браузере. Это хороший финал фундаментальных двух недель: он объясняет, зачем ты всё это учил.","takeaways":["Software 3.0 — это программы, написанные промптами на обычном языке; программировать теперь могут не только программисты.","У LLM «рваный» интеллект: блестящие в одном, неожиданно слабые в другом — их нужно проверять.","Лучше всего работает цикл «ИИ генерирует — человек быстро проверяет», и чем быстрее проверка, тем лучше.","Держи агента на коротком поводке: маленькие изменения, которые легко понять и проверить.","Хорошие продукты дают регулировать уровень автономии ИИ, а не отдают ему всё сразу."],"steps":[{"title":"Посмотри доклад с переводом","detail":"Около 40 минут. Запиши три идеи, которые больше всего относятся к тебе."},{"title":"Оглянись на две недели","detail":"Вспомни, где ты сам был в роли «проверяющего» при работе с агентом. Где проверка была быстрой, а где ты терялся?"},{"title":"Придумай продукт с ползунком автономии","detail":"Возьми идею своего будущего приложения или видео. Опиши, что ИИ делает сам, что предлагает на проверку, а что решает только человек."},{"title":"Выбери трек на дальше","detail":"Дальше программа делится на приложения и видео. Исходя из доклада и своих интересов, реши, что тебе ближе, и запиши почему."}],"exercise":{"title":"Манифест на следующие 52 дня","goal":"Связать идеи доклада со своей целью в программе и выбрать направление.","instructions":["Посмотри доклад и выпиши три ключевые идеи своими словами.","Опиши свой будущий проект (приложение или видео) в 3–4 предложениях.","Распиши уровни автономии: что делает ИИ, что проверяешь ты, как сделать проверку быстрой.","Опубликуй текст в своём Telegram-канале или сохрани как заметку и пришли ссылку или текст."],"proof":"text","estMinutes":30},"quiz":[{"q":"Что Карпаты называет Software 3.0?","options":["Программы на языке C","Программы, которые пишутся промптами на естественном языке","Третью версию Windows","Мобильные приложения"],"answer":1,"explain":"1.0 — код, 2.0 — веса нейросетей, 3.0 — промпты на обычном языке."},{"q":"Как лучше всего организовать работу с ИИ по его мысли?","options":["Дать ИИ полную свободу сразу","Не пользоваться ИИ для важного","Быстрый цикл: ИИ генерирует, человек проверяет","Проверять результат раз в месяц"],"answer":2,"explain":"Скорость цикла «генерация — проверка» определяет продуктивность."},{"q":"Что значит держать агента «на коротком поводке»?","options":["Давать небольшие изменения, которые легко проверить","Ограничивать интернет","Работать только ночью","Запрещать ему писать код"],"answer":0,"explain":"Огромный дифф трудно проверить, а маленький — быстро и надёжно."}],"suggestedDays":[{"day":14,"track":"common","reason":"Финал фундамента: посмотреть на картину целиком и выбрать трек для этапа Build."}],"tracks":["common"],"topics":["agents","career"],"tags":["карпаты","software 3.0","агенты","будущее профессии"],"level":"beginner","estMinutes":70}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-karpathy-software-3');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-karpathy-software-3', 'en', 'ready', '{"title":"Software Is Changing (Again): Karpathy on Software 3.0","hook":"Why writing software in plain English is real programming, and where you fit in that shift.","summary":"In this keynote at Y Combinator''s AI Startup School, Andrej Karpathy describes three eras of software. Software 1.0 is code people write by hand. Software 2.0 is neural networks whose behaviour is learned from data. Software 3.0 is programming large language models with prompts written in plain language.\n\nHe compares LLMs to utilities and to operating systems, describes their strange ''psychology'' (superhuman at some things, oddly weak at others, and forgetful between sessions), and argues for ''partial autonomy'' products: tools where a human stays in the loop, can quickly check the AI''s work, and can slide how much control the AI gets. He also talks about vibe coding, building apps by talking to an AI, and how the hard part often moves to deployment and everything around the code.\n\nThis is a great end-of-foundation talk: it explains why the program teaches you to guide and verify an agent rather than type code from scratch.","takeaways":["Prompts are a new kind of program: plain language can now drive software.","LLMs are powerful but uneven; they can be brilliant and make silly mistakes in the same session.","Good AI tools keep a human in the loop with a fast way to check and accept work.","Work in small, verifiable steps instead of asking for huge changes at once.","Getting code written is now easy; shipping it (deploys, accounts, payments) is often the hard part."],"steps":[{"title":"Watch the full talk","detail":"Note his three eras of software and one example of each."},{"title":"Find your autonomy slider","detail":"Think about how much you let your coding agent do without asking. Write where you are on the slider today and why."},{"title":"Review two weeks of your own work","detail":"Look at what you built in the foundation weeks. Where did you verify carefully, and where did you just accept?"},{"title":"Write your Software 3.0 statement","detail":"In three sentences: what you will build in the next phase and how you will keep the AI on a short leash."}],"exercise":{"title":"Foundation retrospective","goal":"Close the first two weeks with a clear picture of how you work with AI and what you will build next.","instructions":["Write a short retrospective (200–300 words) on your first two weeks.","Include one moment where the agent saved you a lot of time and one where you had to catch its mistake.","Use at least two ideas from the talk (for example: partial autonomy, generation and verification, small steps).","End with which track you choose next (apps or video) and why."],"proof":"text","estMinutes":30},"quiz":[{"q":"In Karpathy''s framing, what is Software 3.0?","options":["Programming LLMs with natural-language prompts","Code written in assembly","Neural network weights trained on data","Software that runs only in the cloud"],"answer":0,"explain":"1.0 is hand-written code, 2.0 is learned weights, 3.0 is prompting LLMs."},{"q":"What does a ''partial autonomy'' product do?","options":["Lets the AI act with no oversight","Forbids AI entirely","Keeps a human in the loop and lets them adjust how much the AI does","Only works offline"],"answer":2,"explain":"The human verifies quickly and controls how much autonomy the AI gets."},{"q":"Why work in small steps with an agent?","options":["Small changes are faster to check, so mistakes get caught early","Large requests are illegal","Agents cannot write more than ten lines","It uses fewer files"],"answer":0,"explain":"Verification is the bottleneck; small diffs keep it fast."}],"suggestedDays":[{"day":14,"track":"common","reason":"Last day of foundation: step back and see the bigger picture before choosing a track."}],"tracks":["common"],"topics":["agents","career"],"tags":["karpathy","software-3","vibe-coding","autonomy"],"level":"beginner","estMinutes":70}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-karpathy-software-3');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-karpathy-software-3', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-karpathy-software-3') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-karpathy-software-3');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-fireship-claude-37', 'youtube', 'https://www.youtube.com/watch?v=x2WtHZciC74', 'https://www.youtube.com/watch?v=x2WtHZciC74', 'x2WtHZciC74', 'Claude 3.7 goes hard for programmers…', 'Fireship', NULL, 348, 'https://i.ytimg.com/vi/x2WtHZciC74/hqdefault.jpg', '["apps"]', '["claude-code","agents"]', 'beginner', 'en', '["en"]', '[]', 'review', 'not_applicable', 'ready', 0, 18, 'seed', NULL);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-fireship-claude-37', 'en', 'ready', '{"title":"Claude 3.7 goes hard for programmers (Fireship)","hook":"A fast, funny snapshot of the release that brought Claude Code into the world, and a lesson in reading AI hype.","summary":"Fireship''s quick video reacts to the launch of Claude 3.7 Sonnet and the first research preview of Claude Code, released at the same time in early 2025. In typical Fireship style it moves fast: what the new model claims, its option to think longer before answering, and a hands-on look at using the command-line agent.\n\nTreat this as a time capsule. Models and tools have moved on since, so specific benchmarks and prices in the video are out of date. What still holds is the shape of working with an agent in the terminal and the healthy scepticism toward launch-day claims.\n\nAs you start the apps track, use it to remind yourself that the tools will keep changing. Your skill is in describing, checking and shipping, not in any single model version.","takeaways":["Claude Code started as a terminal-based agent released alongside Claude 3.7 Sonnet.","Extended thinking lets a model spend more effort on a hard problem before answering.","Launch-day benchmarks are marketing until you test the tool on your own work.","Model versions change quickly; durable skills are about process, not a specific release."],"steps":[{"title":"Watch it once for fun","detail":"It is short. Enjoy the jokes, then go back for the substance."},{"title":"List the claims","detail":"Write down every concrete claim the video mentions about the model or the tool."},{"title":"Check what is current","detail":"Open the Claude Code docs and see which model it uses today and what has changed since."},{"title":"Run your own mini benchmark","detail":"Give your coding agent one small task from your app idea and judge the result yourself."}],"exercise":{"title":"Hype check: my own test","goal":"Form your own opinion of your coding agent based on evidence, not marketing.","instructions":["Pick one small feature for the app you plan to build in this track (for example: a form that saves a note).","Ask Claude Code to build it in a new folder. Time how long it takes and count how many corrections you needed.","Write a short ''review'' (100–200 words): what worked, what did not, and one thing you would ask differently next time."],"proof":"text","estMinutes":45},"quiz":[{"q":"What was released alongside Claude 3.7 Sonnet?","options":["A mobile game","A new web browser","A video editor","A research preview of Claude Code"],"answer":3,"explain":"Claude Code first appeared as a research preview at that launch."},{"q":"What is the best way to judge a new AI tool?","options":["Trust the launch benchmarks","Test it on your own real tasks","Count its social media likes","Choose whichever is newest"],"answer":1,"explain":"Your own work is the benchmark that matters."},{"q":"Why are some details in this video outdated now?","options":["The video was edited later","Fireship deleted parts","Terminals no longer exist","Models, prices and features change quickly"],"answer":3,"explain":"AI tools move fast; focus on durable process skills."}],"suggestedDays":[],"tracks":["apps"],"topics":["claude-code","agents"],"tags":["claude-code","fireship","news","critical-thinking"],"level":"beginner","estMinutes":55}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-fireship-claude-37');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-fireship-claude-37', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-fireship-claude-37') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-fireship-claude-37');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-fireship-remotion', 'youtube', 'https://www.youtube.com/watch?v=deg8bOoziaE', 'https://www.youtube.com/watch?v=deg8bOoziaE', 'deg8bOoziaE', 'This video was made with code. But how?', 'Fireship', NULL, 521, 'https://i.ytimg.com/vi/deg8bOoziaE/hqdefault.jpg', '["video"]', '["remotion","motion-graphics"]', 'beginner', 'en', '["ru","en"]', '[{"day":15,"track":"video"}]', 'published', 'not_applicable', 'ready', 1, 17, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-fireship-remotion', 'ru', 'ready', '{"title":"Видео из кода: как Fireship делает ролики на Remotion","hook":"Девять минут, после которых ты поймёшь, что видео можно программировать так же, как сайт, — и что агент может делать это за тебя.","summary":"Fireship — популярный англоязычный канал о программировании с очень быстрыми и плотными роликами. Здесь он объясняет, как видео можно сделать кодом: с помощью Remotion, библиотеки, где каждый кадр описывается как компонент React — того же инструмента, на котором делают интерфейсы сайтов.\n\nИдея простая и мощная: если видео — это код, то его можно менять, повторять, подставлять данные и генерировать вариации. А значит, ИИ-агент может собирать для тебя анимации, титры и целые ролики по текстовому описанию.\n\nFireship говорит очень быстро, даже для носителей языка. Смело ставь скорость 0.75, включай автоперевод субтитров или закадровый перевод в Яндекс Браузере. Не переживай, если не понял код на экране, — сейчас важно понять сам принцип.","takeaways":["Remotion позволяет описывать видео кодом на React: кадр зависит от номера кадра.","Видео из кода легко менять и тиражировать: поменял текст или данные — получил новый ролик.","Анимация — это значения (позиция, прозрачность, размер), которые плавно меняются от кадра к кадру.","Готовый результат рендерится в обычный видеофайл, например MP4.","Это идеальная работа для ИИ-агента: ты описываешь сцену словами, он пишет код."],"steps":[{"title":"Посмотри ролик на скорости 0.75","detail":"С субтитрами или закадровым переводом. Задача — понять принцип, а не каждую строчку кода."},{"title":"Выпиши термины","detail":"Компонент, кадр (frame), композиция, рендер. Попроси Claude объяснить каждый в одном предложении."},{"title":"Создай проект Remotion с агентом","detail":"В новой папке попроси Claude Code: «Создай проект Remotion с одной композицией и запусти студию для предпросмотра». Он сам выполнит нужные команды."},{"title":"Сделай первую анимацию","detail":"Попроси: «Сделай 5-секундное видео: моё имя плавно появляется в центре, потом снизу выезжает подпись». Смотри результат в браузере."}],"exercise":{"title":"Пятисекундная заставка с твоим именем","goal":"Получить первое видео, созданное кодом, с помощью ИИ-агента.","instructions":["Попроси Claude Code создать проект Remotion в новой папке.","Опиши словами заставку на 5 секунд: твоё имя или название канала, цвета, как появляется текст.","Посмотри предпросмотр в Remotion Studio и попроси агента поправить то, что не нравится.","Отрендери MP4 и сохрани файл."],"proof":"file","estMinutes":60},"quiz":[{"q":"На какой технологии построен Remotion?","options":["Python","Photoshop","React","Excel"],"answer":2,"explain":"В Remotion видео описывается компонентами React."},{"q":"Почему видео из кода удобно делать с ИИ-агентом?","options":["Агент сам снимает видео на камеру","Сцену можно описать словами, а агент напишет и поправит код","Код не нужно проверять","Так видео получается короче"],"answer":1,"explain":"Видео становится текстом-кодом, а с кодом агенты работают отлично."},{"q":"Что такое анимация с точки зрения кода?","options":["Значения свойств, которые меняются в зависимости от номера кадра","Набор GIF-картинок","Музыка, наложенная на видео","Специальный формат файла"],"answer":0,"explain":"Позиция, прозрачность, масштаб вычисляются для каждого кадра."}],"suggestedDays":[{"day":15,"track":"video","reason":"Старт видеотрека: понять идею «видео как код», на которой строится весь трек."}],"tracks":["video"],"topics":["remotion","motion-graphics"],"tags":["remotion","видео из кода","react","моушн-дизайн"],"level":"beginner","estMinutes":75}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-fireship-remotion');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-fireship-remotion', 'en', 'ready', '{"title":"This video was made with code. But how? (Fireship on Remotion)","hook":"See how a whole video can be written as code, which is exactly the kind of code an AI agent can write for you.","summary":"In this short video Fireship explains how he makes videos with Remotion, a tool that lets you build videos using React, the same technology many websites are made with. Each scene is a component, the current frame number drives what is on screen, and Remotion renders all the frames into a normal video file.\n\nThe big idea for this track: if a video is code, then you can describe a video to a coding agent and it can write it. Text that slides in, numbers that count up, charts that grow, captions that pop: all of this becomes a few lines that you can change, reuse and render again.\n\nDo not worry about the React details yet. Watch for the mental model: a video is a function of time, and frames are just snapshots of that function.","takeaways":["Remotion lets you build videos with React components instead of a timeline editor.","Everything on screen is calculated from the current frame number.","Because the video is code, it is easy to change, template and re-render.","This makes video a natural fit for AI coding agents: describe the motion, let the agent write it."],"steps":[{"title":"Watch the video","detail":"Focus on the idea of frames and time, not the syntax."},{"title":"Think in frames","detail":"At 30 frames per second, how many frames is a 5-second clip? (150.) Write down three things you would animate in those 150 frames."},{"title":"Describe a 5-second clip","detail":"Write a short description: background colour, text, how it enters, how it leaves, timing in seconds."},{"title":"Ask your agent to scaffold it","detail":"In a new folder, ask Claude Code to create a Remotion project and build your clip. Let it run the setup commands with your permission."},{"title":"Preview it","detail":"Ask the agent how to open the Remotion preview in your browser and play your clip."}],"exercise":{"title":"My first coded video clip","goal":"Get a 5-second title animation running in the Remotion preview.","instructions":["Write a description of a 5-second title card with your name or project name.","Ask Claude Code to set up a new Remotion project and build that clip.","Open the preview, play it, and ask for one change (colour, speed, or font size).","Take a screenshot of the preview showing your clip and upload it."],"proof":"file","estMinutes":60},"quiz":[{"q":"What does Remotion use to describe a video?","options":["A drag-and-drop timeline","Spreadsheet formulas","React components written in code","Photoshop layers"],"answer":2,"explain":"Scenes are React components rendered frame by frame."},{"q":"What usually decides what is on screen at any moment in a Remotion video?","options":["The current frame number","Random chance","The mouse position","The file name"],"answer":0,"explain":"Animations are calculated from the frame."},{"q":"Why is video-as-code a good fit for AI coding agents?","options":["Agents cannot edit video files at all","Code videos never need rendering","You can describe the motion in words and the agent writes the code","It removes the need for any review"],"answer":2,"explain":"Agents are good at writing code from clear descriptions, and you can still review the result."}],"suggestedDays":[{"day":15,"track":"video","reason":"Opening the video track: the core idea that video can be code."}],"tracks":["video"],"topics":["remotion","motion-graphics"],"tags":["remotion","react","video-as-code","fireship"],"level":"beginner","estMinutes":70}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-fireship-remotion');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-fireship-remotion', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-fireship-remotion') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-fireship-remotion');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-manim-3b1b-demo', 'youtube', 'https://www.youtube.com/watch?v=rbu7Zu5X1zI', 'https://www.youtube.com/watch?v=rbu7Zu5X1zI', 'rbu7Zu5X1zI', 'How I animate 3Blue1Brown | A Manim demo with Ben Sparks', '3Blue1Brown', NULL, 3220, 'https://i.ytimg.com/vi/rbu7Zu5X1zI/hqdefault.jpg', '["video"]', '["motion-graphics","python"]', 'intermediate', 'en', '["ru","en"]', '[{"day":25,"track":"video"}]', 'published', 'not_applicable', 'ready', 0, 16, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-manim-3b1b-demo', 'ru', 'ready', '{"title":"Как анимирует 3Blue1Brown: Manim изнутри","hook":"Грант Сандерсон показывает, как он сам создаёт свои знаменитые анимации кодом. Редкий шанс увидеть рабочий процесс мастера.","summary":"В этом видео автор 3Blue1Brown Грант Сандерсон вместе с математиком и популяризатором Беном Спарксом показывает, как работает Manim — библиотека на Python, на которой сделаны все анимации канала. Ты увидишь живой процесс: как пишется сцена, как он быстро проверяет изменения и итеративно доводит анимацию до нужного вида.\n\nВажный нюанс: Грант пользуется своей версией библиотеки (ManimGL). Для новичков и для работы с агентом лучше брать Manim Community Edition — её поддерживает сообщество, у неё подробная документация. Идеи из видео переносятся, но команды и детали могут отличаться.\n\nВидео длинное (около часа) и на английском. Включи автоперевод субтитров или закадровый перевод в Яндекс Браузере. Сегодня посмотри первые 20–30 минут, чтобы понять подход, а остальное — по желанию.","takeaways":["Manim — библиотека на Python для математических и объясняющих анимаций.","Анимация собирается из объектов (фигуры, текст, формулы) и действий над ними.","Ключ к хорошему результату — быстрый цикл: поменял код, посмотрел, поправил.","Есть две версии: ManimGL Гранта и Manim Community; новичкам лучше вторая.","Объясняющие анимации отлично подходят для обучающих роликов и коротких видео."],"steps":[{"title":"Посмотри первые 20–30 минут","detail":"С переводом. Следи не за синтаксисом, а за процессом: как Грант идёт от идеи к готовой сцене."},{"title":"Попроси агента установить Manim Community","detail":"Скажи Claude Code: «Установи Manim Community Edition и проверь, что он работает». Понадобятся Python и ffmpeg — агент подскажет, чего не хватает."},{"title":"Сделай первую сцену","detail":"Попроси: «Сделай сцену Manim, где круг превращается в квадрат, а потом появляется подпись на русском». Запусти рендер в низком качестве для скорости."},{"title":"Итерируй, как Грант","detail":"Меняй по одной вещи: цвет, скорость, порядок. Каждый раз смотри результат. Так формируется чутьё на анимацию."}],"exercise":{"title":"Анимация одной идеи","goal":"Сделать короткую анимацию в Manim, которая объясняет одну простую мысль.","instructions":["Выбери простую идею: «3 + 2 = 5 яблокам», «как растёт стрик за 66 дней» или любую свою.","Опиши агенту сцену словами: какие объекты, что с ними происходит, сколько секунд.","Отрендери, посмотри и попроси поправить минимум два раза.","Сохрани итоговый видеофайл."],"proof":"file","estMinutes":75},"quiz":[{"q":"Что такое Manim?","options":["Видеоредактор с таймлайном","Библиотека на Python для анимаций кодом","Сервис для стриминга","Плагин для Photoshop"],"answer":1,"explain":"Manim описывает анимации кодом на Python, а потом рендерит их в видео."},{"q":"Какую версию Manim лучше выбрать новичку?","options":["Manim Community Edition","Только ту, что в видео","Любую, разницы нет","Никакую, нужен Blender"],"answer":0,"explain":"У Community Edition подробная документация и активное сообщество; Грант пользуется своей версией ManimGL."},{"q":"Какой рабочий приём из видео самый важный?","options":["Писать всю сцену сразу без проверки","Рисовать кадры вручную","Быстро смотреть результат после каждого изменения","Рендерить только в 4K"],"answer":2,"explain":"Быстрый цикл «поменял — посмотрел» — основа работы над анимацией."}],"suggestedDays":[{"day":25,"track":"video","reason":""}],"tracks":["video"],"topics":["motion-graphics","python"],"tags":["manim","3blue1brown","анимация","python"],"level":"intermediate","estMinutes":100}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-manim-3b1b-demo');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-manim-3b1b-demo', 'en', 'ready', '{"title":"How I animate 3Blue1Brown: a Manim demo with Ben Sparks","hook":"Watch Grant Sanderson build a maths animation live and see how a creator actually works in code.","summary":"Grant Sanderson, creator of 3Blue1Brown, sits down with mathematician Ben Sparks and builds an animation from scratch with Manim, the Python library he created for his videos. The value here is not memorising the code but watching his workflow: he writes a little, runs it, looks, adjusts, and repeats, in very short loops.\n\nOne important detail: Grant uses his own version of Manim (often called ManimGL). Most beginners, and most tutorials, use Manim Community Edition, which is a separate, community-maintained fork. Code from this video may not run unchanged in the Community version. That is fine; you are here for the way of working.\n\nThe video is close to an hour long. Watch the first 20 minutes today to absorb the workflow, and come back to the rest when you are building your own scenes.","takeaways":["Manim is a Python library for precise, programmatic animation, originally made for 3Blue1Brown.","Fast feedback loops matter more than perfect code: change, run, look, repeat.","There are two main versions: Grant''s ManimGL and the separate Manim Community Edition.","Complex animations are built from many small, simple moves."],"steps":[{"title":"Watch the first 20 minutes","detail":"Pay attention to how often Grant runs his code to look at the result."},{"title":"Note the building blocks","detail":"Write down the kinds of objects and moves he uses: shapes, text, equations, movements, transformations."},{"title":"Ask your agent which Manim to use","detail":"Ask Claude Code to explain the difference between ManimGL and Manim Community and which one is easier to install on your computer."},{"title":"Install and run a test scene","detail":"Ask the agent to install Manim Community and render a simple scene: a square that turns into a circle."}],"exercise":{"title":"Square to circle","goal":"Render your first Manim animation and practise the change-run-look loop.","instructions":["With Claude Code, install Manim Community Edition (it will need Python and a few system tools; let the agent guide you).","Render a scene where a square transforms into a circle.","Make three small changes, one at a time, re-rendering each time: colour, speed, and an added text label.","Upload the final video file or a screenshot of its last frame."],"proof":"file","estMinutes":75},"quiz":[{"q":"Which language is Manim written in and used with?","options":["JavaScript","Python","Swift","C#"],"answer":1,"explain":"Manim scenes are Python classes."},{"q":"What is the key difference between ManimGL and Manim Community?","options":["One is for music, one for video","Manim Community is paid","There is no difference","They are separate versions; code may not transfer directly between them"],"answer":3,"explain":"Grant uses ManimGL; most tutorials use the Community fork."},{"q":"What habit does the demo show that you should copy?","options":["Write the whole scene before running anything","Run the code often and adjust in small steps","Avoid previews","Only use templates"],"answer":1,"explain":"Short feedback loops are how good animations get made."}],"suggestedDays":[{"day":25,"track":"video","reason":""}],"tracks":["video"],"topics":["motion-graphics","python"],"tags":["manim","3blue1brown","animation","python"],"level":"intermediate","estMinutes":100}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-manim-3b1b-demo');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-manim-3b1b-demo', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-manim-3b1b-demo') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-manim-3b1b-demo');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-git-ru-basics', 'youtube', 'https://www.youtube.com/watch?v=bkNCylkzFRk', 'https://www.youtube.com/watch?v=bkNCylkzFRk', 'bkNCylkzFRk', 'Изучение Git для новичков / #1 - Что такое Git, установка и настройка', NULL, NULL, NULL, 'https://i.ytimg.com/vi/bkNCylkzFRk/hqdefault.jpg', '["common"]', '["git"]', 'beginner', 'ru', '["ru"]', '[{"day":2,"track":"common"},{"day":6,"track":"common"}]', 'published', 'not_applicable', 'ready', 0, 15, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-git-ru-basics', 'ru', 'ready', '{"title":"Git с нуля: что это такое и как его установить","hook":"Русскоязычный вводный урок про Git: что это, зачем он нужен и как его поставить и настроить. Без перевода и без лишней теории.","summary":"Это первый урок русскоязычного курса по Git для новичков. В нём объясняют, что такое система контроля версий, зачем она нужна, как установить Git и сделать первичную настройку.\n\nGit — это «машина времени» для проекта: он запоминает версии файлов, и ты всегда можешь вернуться назад или посмотреть, что изменилось. Для работы с ИИ-агентом это особенно важно: агент меняет много файлов, и Git позволяет спокойно откатить неудачный эксперимент.\n\nДаже если агент умеет сам делать коммиты (сохранённые снимки проекта), тебе нужно понимать, что происходит. Этот урок даёт ровно ту базу, которая нужна на старте. Если в видео что-то устарело (например, интерфейс установщика), сверяйся с официальным сайтом git-scm.com.","takeaways":["Git сохраняет историю изменений проекта и позволяет вернуться к любой сохранённой версии.","Коммит — это снимок проекта в определённый момент с коротким описанием.","После установки Git нужно указать своё имя и почту — они будут подписывать коммиты.","Git работает локально на твоём компьютере; GitHub — это отдельный сервис для хранения репозиториев в интернете.","С Git эксперименты с агентом безопасны: неудачное всегда можно откатить."],"steps":[{"title":"Посмотри урок","detail":"Видео на русском. Держи терминал открытым и повторяй действия по ходу."},{"title":"Установи Git","detail":"Скачай с git-scm.com или попроси Claude Code проверить, установлен ли Git (команда git --version), и подсказать, как поставить его на твою систему."},{"title":"Настрой имя и почту","detail":"Выполни git config --global user.name \"Твоё Имя\" и git config --global user.email \"твоя@почта\". Почту лучше указывать ту же, что будет на GitHub."},{"title":"Сделай первый репозиторий","detail":"В новой папке выполни git init, создай файл с парой строк, затем git add . и git commit -m \"Первый коммит\". Проверь git log."},{"title":"Попроси агента объяснить","detail":"Спроси Claude Code: «Объясни простыми словами, что сейчас произошло в этом репозитории». Сравни с тем, как ты понял сам."}],"exercise":{"title":"Мой первый коммит","goal":"Установить и настроить Git и сделать свой первый репозиторий с несколькими коммитами.","instructions":["Установи Git и проверь командой git --version.","Настрой user.name и user.email.","Создай папку, выполни git init и сделай три коммита: создание файла и две правки.","Выполни git log --oneline и скопируй вывод."],"proof":"text","estMinutes":40},"quiz":[{"q":"Зачем нужен Git?","options":["Чтобы ускорить интернет","Чтобы хранить историю изменений проекта","Чтобы рисовать интерфейсы","Чтобы запускать сайты"],"answer":1,"explain":"Git — система контроля версий: она хранит историю и позволяет вернуться назад."},{"q":"Что такое коммит?","options":["Снимок состояния проекта с описанием","Ошибка в коде","Сайт в интернете","Пароль от GitHub"],"answer":0,"explain":"Коммит фиксирует изменения в определённый момент, к нему можно вернуться."},{"q":"Чем Git отличается от GitHub?","options":["Это одно и то же","Git платный, GitHub бесплатный","GitHub работает только на Mac","Git — программа на компьютере, GitHub — сервис для хранения репозиториев онлайн"],"answer":3,"explain":"Git работает локально, а GitHub — один из сервисов, где можно хранить и показывать репозитории."}],"suggestedDays":[{"day":2,"track":"common","reason":""},{"day":6,"track":"common","reason":""}],"tracks":["common"],"topics":["git"],"tags":["git","контроль версий","установка","на русском"],"level":"beginner","estMinutes":50}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-git-ru-basics');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-git-ru-basics', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-git-ru-basics') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-git-ru-basics');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-cc-docs-overview', 'link', 'https://code.claude.com/docs/en/overview', 'https://code.claude.com/docs/en/overview', NULL, 'Claude Code overview', 'Anthropic', 'Claude Code is an agentic coding tool that reads your codebase, edits files, runs commands, and integrates with your development tools. Available in your terminal, IDE, desktop app, and browser.', NULL, NULL, '["common"]', '["claude-code"]', 'beginner', 'en', '["ru","en"]', '[{"day":1,"track":"common"}]', 'published', 'not_applicable', 'ready', 1, 14, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-cc-docs-overview', 'ru', 'ready', '{"title":"Claude Code: официальный обзор и установка","hook":"Официальная страница документации: что такое Claude Code, где он работает и как его поставить. Отсюда начинается твоя работа с агентом.","summary":"Это главная страница документации Claude Code от Anthropic. Здесь коротко объяснено, что это за инструмент: агент для программирования, который читает код твоего проекта, правит файлы, запускает команды и подключается к твоим инструментам. Работать с ним можно в терминале, в редакторе кода, в десктопном приложении и в браузере.\n\nДокументация на английском, но её легко читать через встроенный переводчик в браузере (Chrome, Яндекс Браузер, Edge). Команды и код не переводи — копируй их как есть.\n\nПро доступ: для работы нужен аккаунт Claude с подпиской или API-ключ. Сервисы Anthropic официально доступны не во всех странах, и из некоторых регионов, включая Россию, может понадобиться VPN, а оплата российскими картами может не пройти. Разберись с этим заранее, чтобы не застрять в день установки. Если доступа пока нет, всё равно прочитай страницу — понимание пригодится.","takeaways":["Claude Code — агент, который работает с твоим проектом: читает, меняет, запускает и проверяет.","Им можно пользоваться в терминале, в IDE, в десктоп-приложении и в браузере.","Для работы нужен аккаунт Claude (подписка) или API-ключ; доступность и оплата зависят от региона.","Документация — главный источник правды: интерфейс меняется быстро, и видео могут устаревать."],"steps":[{"title":"Прочитай страницу с переводчиком","detail":"Включи перевод страницы в браузере. Отметь, какие способы запуска есть и какие требования к системе."},{"title":"Реши вопрос с доступом","detail":"Проверь, что у тебя есть аккаунт Claude и способ оплаты подписки или API. Если из твоего региона сервис недоступен, разберись заранее, какие законные варианты доступа у тебя есть."},{"title":"Установи Claude Code","detail":"Следуй разделу установки на странице для своей ОС. Копируй команды целиком, без перевода."},{"title":"Первый запуск","detail":"Открой терминал в пустой папке, выполни claude и войди в аккаунт. Напиши: «Привет! Расскажи, что ты умеешь в этой папке»."},{"title":"Маленькая задача","detail":"Попроси: «Создай файл index.html с простой страницей обо мне». Открой файл в браузере."}],"exercise":{"title":"Агент установлен и работает","goal":"Установить Claude Code и выполнить первую реальную задачу.","instructions":["Установи Claude Code по инструкции на странице.","Запусти его в новой папке и войди в аккаунт.","Попроси создать простую HTML-страницу о себе (имя, пара фраз, любимое занятие).","Открой страницу в браузере и сделай скриншот рядом с окном терминала."],"proof":"file","estMinutes":45},"quiz":[{"q":"Что умеет Claude Code?","options":["Только отвечать на вопросы в чате","Только переводить тексты","Читать проект, менять файлы и запускать команды","Только рисовать картинки"],"answer":2,"explain":"Это агент: он действует в твоём проекте, а не только пишет текст."},{"q":"Что делать с командами при чтении документации через переводчик?","options":["Копировать как есть, без перевода","Переводить на русский","Пропускать","Переписывать по памяти"],"answer":0,"explain":"Переводчик может испортить команду — копируй её из оригинала."},{"q":"Почему стоит опираться на документацию, а не только на видео?","options":["Видео всегда неправильные","Интерфейс и команды быстро меняются, а документацию обновляют","Документацию нельзя перевести","Видео запрещены"],"answer":1,"explain":"Видео фиксирует момент записи, а документация актуальна."}],"suggestedDays":[{"day":1,"track":"common","reason":""}],"tracks":["common"],"topics":["claude-code"],"tags":["claude code","установка","документация","доступ"],"level":"beginner","estMinutes":50}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-cc-docs-overview');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-cc-docs-overview', 'en', 'ready', '{"title":"Claude Code overview: what it is and how to install it","hook":"The official starting point: install Claude Code and run your first session today.","summary":"This page from the Claude Code documentation explains what the tool is and how to get it running. Claude Code is an agentic coding tool: it reads your project, edits files, runs commands and works with your development tools. You can use it in the terminal, inside code editors, in a desktop app and in the browser.\n\nThe page gives installation instructions and a short first-run walkthrough, plus links to the rest of the docs for when you need them. Installation steps change from time to time, so always follow the current version of this page rather than an old video or blog post.\n\nToday''s goal is simple: get Claude Code installed, sign in, and have one real conversation with it in a folder on your computer.","takeaways":["Claude Code is an agent that works inside your project: reading, editing and running commands.","It runs in several places: terminal, editors, desktop app and browser.","Always follow the current docs for installation; steps change over time.","You start it inside a project folder, and that folder is what it works on."],"steps":[{"title":"Read the overview page","detail":"Note which ways of using Claude Code are available and which one you will start with."},{"title":"Install it","detail":"Follow the install instructions for your operating system exactly. If a command fails, copy the full error message somewhere safe."},{"title":"Sign in","detail":"Complete the login flow the first time you run it."},{"title":"Start a first session","detail":"Create a new empty folder, open a terminal in it, start Claude Code and ask: ''What can you help me with in this folder?''"},{"title":"Make one small file","detail":"Ask it to create a text file called hello.txt with a short note to yourself, then open the file to check."}],"exercise":{"title":"Hello from my agent","goal":"Have Claude Code installed and prove it can create a file on your computer.","instructions":["Install Claude Code using the official overview page.","In a new folder, start a session and ask it to create hello.txt containing today''s date and one sentence about why you joined this program.","Approve the file write when it asks.","Paste the contents of hello.txt, or a screenshot of your terminal, as proof."],"proof":"text","estMinutes":30},"quiz":[{"q":"What does Claude Code work on when you start it?","options":["Your whole hard drive automatically","The project folder you start it in","Only files on the internet","Nothing until you upload files"],"answer":1,"explain":"It works in the folder where you launch it."},{"q":"Where should you get installation steps from?","options":["Any old tutorial","A friend''s screenshot from last year","You guess the command","The current official docs"],"answer":3,"explain":"Install steps change; the docs are kept up to date."},{"q":"If an install command fails, what is the most useful thing to do?","options":["Restart and hope","Copy the full error message and share it when asking for help","Delete the folder","Skip the step"],"answer":1,"explain":"Exact error messages make problems much easier to solve."}],"suggestedDays":[{"day":1,"track":"common","reason":""}],"tracks":["common"],"topics":["claude-code"],"tags":["claude-code","install","docs","setup"],"level":"beginner","estMinutes":40}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-cc-docs-overview');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-cc-docs-overview', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-cc-docs-overview') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-cc-docs-overview');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-cc-best-practices', 'link', 'https://code.claude.com/docs/en/best-practices', 'https://code.claude.com/docs/en/best-practices', NULL, 'Best practices for Claude Code', 'Anthropic', NULL, NULL, NULL, '["common"]', '["claude-code","workflow","prompting"]', 'intermediate', 'en', '["ru","en"]', '[{"day":4,"track":"common"}]', 'published', 'not_applicable', 'ready', 0, 13, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-cc-best-practices', 'ru', 'ready', '{"title":"Лучшие практики Claude Code: как работать без хаоса","hook":"Официальное руководство от Anthropic: проверенные приёмы, которые отделяют «агент что-то натворил» от «агент сделал ровно то, что нужно».","summary":"Это страница документации, где Anthropic собрала советы по эффективной работе с Claude Code. Главная мысль: агенту нужен способ проверить себя — тесты, скриншоты, ожидаемый вывод. Когда он может сам убедиться, что всё работает, качество резко растёт.\n\nДругие важные идеи: сначала изучить и спланировать, потом писать код; давать конкретные задачи с контекстом; держать в CLAUDE.md правила проекта; следить за контекстом — когда разговор разросся и ушёл в сторону, начинать заново (например, через /clear); вовремя прерывать агента и корректировать курс.\n\nСтраница на английском и довольно длинная. Читай через переводчик в браузере. Сегодня сфокусируйся на разделах про проверку результата, про цикл «изучи — спланируй — сделай» и про управление контекстом. Остальное — справочник на потом.","takeaways":["Дай агенту способ проверить свою работу: тесты, скриншоты, конкретный ожидаемый результат.","Сначала исследование и план, потом код — особенно для задач больше пары строк.","Конкретный промпт с контекстом экономит итерации: какие файлы, какое поведение, как проверить.","Следи за контекстом: длинная запутанная сессия хуже свежей с ясной задачей.","Корректируй рано: если агент пошёл не туда, останови его и поправь, не жди конца."],"steps":[{"title":"Прочитай ключевые разделы","detail":"Через переводчик в браузере. Выпиши по одному приёму из разделов про проверку, планирование и контекст."},{"title":"Добавь проверку в задачу","detail":"В своём проекте дай задачу с критерием готовности: «Добавь кнопку… Готово, когда открыл страницу, нажал кнопку и увидел…». Попроси агента сделать скриншот или запустить проверку."},{"title":"Потренируйся прерывать","detail":"Дай задачу и, если агент пошёл не туда, нажми Esc и поправь направление. Это нормально и полезно."},{"title":"Начни с чистого листа","detail":"Когда переходишь к новой задаче, используй /clear. Сравни, насколько ответы стали точнее."},{"title":"Обнови CLAUDE.md","detail":"Допиши туда правила, которые выучил сегодня: например, «перед завершением задачи проверь результат в браузере»."}],"exercise":{"title":"Задача с проверкой","goal":"Выполнить фичу в своём проекте так, чтобы агент сам подтвердил результат.","instructions":["Выбери небольшое улучшение для своей страницы или проекта.","Попроси агента сначала изучить код и предложить план, без правок.","Сформулируй критерий готовности и попроси агента проверить его самому (тест, скриншот или запуск).","Запиши промпт, который ты дал, и что агент сделал для проверки."],"proof":"text","estMinutes":50},"quiz":[{"q":"Что сильнее всего повышает качество работы агента по этому руководству?","options":["Длинные эмоциональные промпты","Работа без CLAUDE.md","Способ проверить результат: тесты, скриншоты, ожидаемый вывод","Как можно больше задач в одном сообщении"],"answer":2,"explain":"Когда агент может проверить себя, он находит и исправляет ошибки сам."},{"q":"Что делать, если агент явно пошёл не туда?","options":["Дождаться конца и всё удалить","Остановить его (Esc) и скорректировать направление","Закрыть терминал","Ничего, он сам разберётся"],"answer":1,"explain":"Ранняя корректировка экономит время и токены."},{"q":"Когда стоит очищать контекст (например, /clear)?","options":["При переходе к новой, несвязанной задаче","После каждого сообщения","Никогда","Только при ошибках установки"],"answer":0,"explain":"Лишний контекст от старой задачи может сбивать агента в новой."}],"suggestedDays":[{"day":4,"track":"common","reason":""}],"tracks":["common"],"topics":["claude-code","workflow","prompting"],"tags":["claude code","лучшие практики","проверка","контекст"],"level":"intermediate","estMinutes":70}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-cc-best-practices');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-cc-best-practices', 'en', 'ready', '{"title":"Best practices for Claude Code","hook":"The official guide to getting consistently good results from your agent instead of lucky ones.","summary":"This page collects the habits that make Claude Code reliable. The recurring themes: give the agent a way to verify its own work (run the app, run tests, compare with a screenshot), explore and plan before writing code, give specific context instead of vague requests, and set up your environment with a CLAUDE.md file so it knows your project''s rules.\n\nIt also covers managing a session: correcting course early, clearing the conversation when you switch to an unrelated task so old context does not confuse it, and, for later, ways to automate and scale up such as running Claude in scripts or in parallel.\n\nFor now, focus on the first sections about verification, planning, specific prompts and CLAUDE.md. Skim the more advanced parts so you know they exist; you will come back to them in the Ship phase.","takeaways":["The single biggest improvement is giving the agent a way to check its own work.","Explore, then plan, then code, then commit: separating these steps prevents wasted work.","Specific requests (which file, what behaviour, what it should look like) get better results than vague ones.","Keep CLAUDE.md short and useful: commands, conventions and gotchas for this project.","Clear the context between unrelated tasks so old details do not get in the way."],"steps":[{"title":"Read the verification and planning sections","detail":"Write down how you could let the agent check your current project (for example, by opening the page in a browser and taking a screenshot)."},{"title":"Rewrite a vague request","detail":"Take a past request like ''make it look better'' and rewrite it with specifics: which page, which elements, what feeling, what to leave alone."},{"title":"Improve your CLAUDE.md","detail":"Ask Claude to review your project''s CLAUDE.md against the page''s advice and suggest a shorter, clearer version."},{"title":"Practise clearing context","detail":"When you finish a task, clear the conversation before starting an unrelated one, and notice whether answers stay focused."}],"exercise":{"title":"Before and after: one feature, two ways","goal":"See the difference good practices make on a real change to your project.","instructions":["Pick one small improvement to your first web page.","Write a vague request and a specific one (with what to change, what to keep, and how to check it).","Use the specific version with Claude Code, asking it to plan first and to verify the result itself.","Write a short note comparing the two requests and what the agent did, plus your updated CLAUDE.md."],"proof":"text","estMinutes":60},"quiz":[{"q":"According to the guide, what is one of the most effective things you can do?","options":["Give the agent a way to verify its work","Use longer words","Never read its plans","Keep all tasks in one endless conversation"],"answer":0,"explain":"Verification lets the agent catch and fix its own mistakes."},{"q":"What is a good order for a non-trivial change?","options":["Code, then plan, then explore","Commit, then code","Explore, plan, code, commit","Skip straight to commit"],"answer":2,"explain":"Understanding and planning first avoids building the wrong thing."},{"q":"When should you clear the conversation context?","options":["When switching to an unrelated task","Never","After every single message","Only when the computer restarts"],"answer":0,"explain":"Stale context from another task can distract the agent."},{"q":"What belongs in CLAUDE.md?","options":["Your API keys","The entire chat history","Short project rules, commands and conventions","Random notes about anything"],"answer":2,"explain":"Keep it concise and relevant; never put secrets there."}],"suggestedDays":[{"day":4,"track":"common","reason":""}],"tracks":["common"],"topics":["claude-code","workflow","prompting"],"tags":["claude-code","best-practices","verification","claude-md"],"level":"intermediate","estMinutes":85}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-cc-best-practices');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-cc-best-practices', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-cc-best-practices') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-cc-best-practices');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-building-effective-agents', 'link', 'https://www.anthropic.com/research/building-effective-agents', 'https://anthropic.com/research/building-effective-agents', NULL, 'Building effective agents', 'Anthropic', NULL, NULL, NULL, '["apps"]', '["agents","apis"]', 'intermediate', 'en', '["ru","en"]', '[{"day":26,"track":"apps"}]', 'published', 'not_applicable', 'ready', 0, 12, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-building-effective-agents', 'ru', 'ready', '{"title":"Как строить эффективных агентов: статья Anthropic","hook":"Классическая статья о том, как устроены ИИ-агенты и почему лучшие из них проще, чем кажется. Обязательна, если твоё приложение использует LLM.","summary":"В этой статье Anthropic делится опытом создания агентных систем. Главная мысль: успешные решения обычно строятся из простых, понятных шаблонов, а не из сложных фреймворков. Начинай с самого простого варианта и добавляй сложность только тогда, когда она реально улучшает результат.\n\nАвторы различают два типа систем. Workflows — когда шаги заданы кодом заранее: цепочка промптов, маршрутизация по типу запроса, параллельная обработка, оркестратор с исполнителями, цикл «генератор — оценщик». Агенты — когда модель сама решает, какие шаги и инструменты использовать, в цикле с обратной связью от среды. Отдельно подчёркнуто: инструменты для агента нужно проектировать так же внимательно, как интерфейс для человека.\n\nСтатья на английском — читай через переводчик в браузере. Для этапа Build это настоящая карта: когда будешь встраивать ИИ в своё приложение, ты увидишь, какой из шаблонов тебе нужен.","takeaways":["Начинай с простого: часто хватает одного хорошего запроса к модели, без агента.","Workflow — шаги заданы заранее в коде; агент — модель сама выбирает шаги и инструменты.","Базовые шаблоны: цепочка промптов, маршрутизация, параллелизация, оркестратор-исполнители, генератор-оценщик.","Описания инструментов для модели заслуживают такого же внимания, как и промпты.","Автономия стоит дороже и рискованнее — нужны проверки и ограничения."],"steps":[{"title":"Прочитай статью с переводчиком","detail":"Составь для себя таблицу: название шаблона — когда применять — пример из жизни."},{"title":"Нарисуй свой проект","detail":"Возьми своё приложение из трека и нарисуй, где в нём вызывается LLM. Это workflow или агент?"},{"title":"Выбери самый простой вариант","detail":"Спроси себя: можно ли решить задачу одним запросом? Двумя последовательными? Агент нужен, только если шаги заранее неизвестны."},{"title":"Реализуй цепочку с агентом","detail":"Попроси Claude Code реализовать в твоём проекте простую цепочку из двух запросов к модели (например, сначала извлечь данные, потом сгенерировать текст). Без API-ключа — с заглушкой и понятным сообщением «ИИ не настроен»."}],"exercise":{"title":"Архитектура ИИ-части моего приложения","goal":"Выбрать подходящий шаблон из статьи для своего проекта и обосновать выбор.","instructions":["Опиши, что ИИ делает в твоём приложении, в 2–3 предложениях.","Выбери шаблон из статьи (или «одного запроса хватит») и объясни почему.","Нарисуй схему: вход пользователя → шаги → результат.","Перечисли, что может пойти не так и как ты это проверишь."],"proof":"file","estMinutes":45},"quiz":[{"q":"Какой главный совет дают авторы?","options":["Сразу брать самый сложный фреймворк","Начинать с простого и усложнять только при необходимости","Всегда делать полностью автономного агента","Не использовать инструменты"],"answer":1,"explain":"Простые составные шаблоны чаще оказываются надёжнее и дешевле."},{"q":"Чем workflow отличается от агента?","options":["В workflow шаги заданы кодом, агент сам выбирает шаги","Workflow всегда медленнее","Агент не использует LLM","Разницы нет"],"answer":0,"explain":"У агента модель сама управляет процессом, у workflow путь заранее прописан."},{"q":"Какой шаблон подходит, если нужно генерировать текст и сразу оценивать его качество в цикле?","options":["Маршрутизация","Параллелизация","Генератор — оценщик","Один запрос"],"answer":2,"explain":"Один вызов генерирует, другой оценивает и даёт обратную связь — и так по кругу."}],"suggestedDays":[{"day":26,"track":"apps","reason":""}],"tracks":["apps"],"topics":["agents","apis"],"tags":["агенты","архитектура","workflow","llm в приложении"],"level":"intermediate","estMinutes":60}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-building-effective-agents');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-building-effective-agents', 'en', 'ready', '{"title":"Building effective agents (Anthropic)","hook":"A clear, practical map of agent patterns, with the advice to start simple and add complexity only when it pays off.","summary":"This article from Anthropic distils what they learned working with teams that build AI agents. It separates workflows, where code follows a fixed path and calls a model at certain steps, from agents, where the model decides its own steps and tool use as it goes. The building block for both is an ''augmented'' model that can use retrieval, tools and memory.\n\nIt then walks through common workflow patterns: prompt chaining (one step feeds the next), routing (classify the input, send it to the right handler), parallelization (split work or ask several times and combine), orchestrator and workers (one model hands out subtasks), and evaluator and optimizer (one model drafts, another critiques). Finally it covers when a true agent makes sense and why clear tool design matters as much as prompt design.\n\nThe main advice is to start with the simplest thing that works, often a single well-written model call, and add steps only when they measurably help. Read the whole article; it is not long, and you will use these names for the rest of the program.","takeaways":["Workflows follow predefined steps; agents choose their own steps and tools dynamically.","Start with the simplest solution, often one good prompt, and add complexity only when it helps.","Common patterns: prompt chaining, routing, parallelization, orchestrator-workers, evaluator-optimizer.","Tools need clear names, descriptions and examples; design them as carefully as prompts.","Agents trade cost and predictability for flexibility, so test them carefully."],"steps":[{"title":"Read the article end to end","detail":"Make a one-line definition for each pattern as you go."},{"title":"Map patterns to your app","detail":"For the app you are building, write which pattern (if any) fits an AI feature you want."},{"title":"Start with one call","detail":"Ask Claude Code to add a single AI call to your app with a fixed prompt. Use a fallback text if no API key is configured."},{"title":"Add one pattern if it helps","detail":"If the single call is not good enough, ask the agent to turn it into a two-step chain or add an evaluator step, and compare results."}],"exercise":{"title":"Pattern map for my app","goal":"Decide, on paper first, the simplest AI design for one feature of your app.","instructions":["Describe one AI-powered feature of your app in two sentences.","Draw the simplest design (likely one model call) and one more advanced pattern from the article.","Write when you would switch from the simple design to the advanced one, using a concrete signal (for example: answers are wrong more than one time in five).","Upload a photo or screenshot of the diagram with your notes."],"proof":"file","estMinutes":50},"quiz":[{"q":"What is the main difference between a workflow and an agent in this article?","options":["Workflows use no model at all","Agents never use tools","There is no difference","Workflows follow predefined paths; agents direct their own steps"],"answer":3,"explain":"Control flow is fixed in workflows and model-driven in agents."},{"q":"Which pattern sends each input to a specialised handler based on its type?","options":["Prompt chaining","Routing","Evaluator-optimizer","Parallelization"],"answer":1,"explain":"Routing classifies first, then dispatches."},{"q":"What does the article recommend as a starting point?","options":["A multi-agent framework","Fine-tuning your own model","Always building a full agent","The simplest solution that works, then add complexity if needed"],"answer":3,"explain":"Simplicity first; complexity only when it measurably helps."},{"q":"In evaluator-optimizer, what do the two roles do?","options":["Both write code in parallel","One generates a response, the other critiques it for another round","One pays, one deploys","One translates, one summarises"],"answer":1,"explain":"It is a draft-and-feedback loop."}],"suggestedDays":[{"day":26,"track":"apps","reason":""}],"tracks":["apps"],"topics":["agents","apis"],"tags":["agents","workflows","patterns","architecture"],"level":"intermediate","estMinutes":80}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-building-effective-agents');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-building-effective-agents', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-building-effective-agents') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-building-effective-agents');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-prompt-engineering', 'link', 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', 'https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview', NULL, 'Prompt engineering overview', 'Anthropic', NULL, NULL, NULL, '["common"]', '["prompting"]', 'beginner', 'en', '["ru","en"]', '[{"day":4,"track":"common"},{"day":18,"track":"apps"}]', 'published', 'not_applicable', 'ready', 0, 11, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-prompt-engineering', 'ru', 'ready', '{"title":"Промптинг по-взрослому: обзор от Anthropic","hook":"Официальная карта техник промпт-инжиниринга от создателей Claude: с чего начать и что пробовать, когда ответ не тот.","summary":"Промпт — это текст запроса, который ты даёшь модели. Эта страница документации Anthropic — входная точка в раздел о промпт-инжиниринге: как формулировать запросы так, чтобы Claude делал именно то, что нужно.\n\nСначала там советуют определить, как выглядит успешный результат и как его проверить, и только потом улучшать промпт. Дальше — набор техник: быть ясным и конкретным, давать примеры, позволять модели подумать перед ответом, структурировать промпт XML-тегами, задавать роль через системный промпт, разбивать сложную задачу на цепочку запросов. Каждая техника раскрыта на отдельной странице.\n\nДокументация на английском, читай через переводчик в браузере. Отличная новость: Claude прекрасно понимает русский, так что все техники можно применять, сразу формулируя промпты по-русски.","takeaways":["Сначала реши, что такое хороший результат и как ты его проверишь, а потом улучшай промпт.","Ясность и конкретика решают больше, чем «волшебные слова»: контекст, цель, формат ответа.","Примеры желаемого результата часто работают лучше длинных объяснений.","Дай модели подумать: попроси сначала рассуждать, потом отвечать.","Сложную задачу лучше разбить на несколько последовательных запросов."],"steps":[{"title":"Прочитай обзор и список техник","detail":"Через переводчик. Открой 2–3 подстраницы, которые кажутся самыми полезными, например про ясность и примеры."},{"title":"Напиши плохой промпт","detail":"Например: «Напиши пост про мой проект». Отправь Claude и сохрани ответ."},{"title":"Улучши его по технике","detail":"Добавь контекст (кто ты, для кого пост), цель, формат (длина, тон, площадка — например, Telegram-канал) и пример поста, который тебе нравится."},{"title":"Сравни результаты","detail":"Положи два ответа рядом и запиши, что изменилось. Это лучший способ прочувствовать технику."}],"exercise":{"title":"До и после: прокачка одного промпта","goal":"На своём примере увидеть, как техники промптинга меняют качество ответа.","instructions":["Выбери реальную задачу: пост в Telegram, письмо, описание проекта.","Отправь короткий «наивный» промпт и сохрани ответ.","Перепиши промпт, применив минимум три техники со страницы, и отправь снова.","Сохрани оба промпта и оба ответа и подпиши, какие техники ты применил."],"proof":"text","estMinutes":35},"quiz":[{"q":"С чего советуют начинать работу над промптом?","options":["С поиска волшебной фразы","С перевода промпта на английский","С самого длинного промпта","С определения критериев успеха и способа проверки"],"answer":3,"explain":"Без понимания, что такое «хорошо», невозможно понять, стал ли промпт лучше."},{"q":"Какая техника помогает показать модели нужный формат?","options":["Примеры желаемого результата","Писать капслоком","Угрожать модели","Убирать контекст"],"answer":0,"explain":"Пара хороших примеров часто объясняет формат лучше слов."},{"q":"Что делать со сложной многошаговой задачей?","options":["Уместить всё в одно предложение","Отказаться от ИИ","Разбить на цепочку последовательных запросов","Просить ответить одним словом"],"answer":2,"explain":"Цепочка простых шагов надёжнее одного огромного запроса."}],"suggestedDays":[{"day":4,"track":"common","reason":""},{"day":18,"track":"apps","reason":""}],"tracks":["common"],"topics":["prompting"],"tags":["промптинг","техники","документация","claude"],"level":"beginner","estMinutes":50}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-prompt-engineering');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-prompt-engineering', 'en', 'ready', '{"title":"Prompt engineering overview (Claude docs)","hook":"The official starting point for writing prompts that get what you actually want.","summary":"This page opens Anthropic''s prompt engineering guide. Before any techniques, it asks you to have three things: a clear idea of what success looks like, a way to test against that, and a first draft prompt to improve. Prompting is treated as an iterative process, not magic words.\n\nIt then points to a set of techniques, roughly from most broadly useful to more specialised: being clear and direct, giving examples, letting the model think step by step, structuring prompts with tags, giving the model a role, chaining prompts together, and tips for long documents. Each technique has its own page.\n\nToday, read the overview and the ''be clear and direct'' page. If you have more time, read the pages on examples and on letting Claude think. Everything here applies to talking with your coding agent too.","takeaways":["Define what a good answer looks like before you start writing prompts.","Prompting is iterative: draft, test, adjust.","Being clear and direct is the most widely useful technique.","Examples, step-by-step thinking and clear structure each improve results in different situations."],"steps":[{"title":"Read the overview","detail":"List the techniques it links to in your own words."},{"title":"Read ''be clear and direct''","detail":"Note its advice about giving context: who the output is for, what it is for, and what done looks like."},{"title":"Pick a real task","detail":"Choose something you need this week, for example a short bio for your first web page."},{"title":"Write a weak and a strong prompt","detail":"Write a one-line prompt, then a clear one with context, audience, length and an example of the tone you want."},{"title":"Compare results","detail":"Run both in an AI assistant and note what changed."}],"exercise":{"title":"Prompt makeover","goal":"Show, with a real before and after, how a clear prompt changes the result.","instructions":["Choose a real writing task you need (a bio, a page intro, a short message).","Write a quick one-line prompt and save the result.","Rewrite it using at least two techniques from the guide (for example: clear context and an example).","Paste both prompts and both results, plus two sentences on what improved."],"proof":"text","estMinutes":35},"quiz":[{"q":"What does the guide suggest having before you start prompt engineering?","options":["A paid plan","A fine-tuned model","Success criteria, a way to test, and a first draft","At least ten examples"],"answer":2,"explain":"You need to know what good looks like and how to check it."},{"q":"Which technique is described as broadly useful for almost any task?","options":["Being clear and direct","Prompt chaining","Long-context tips","Prefilling"],"answer":0,"explain":"Clear, direct instructions with context help everywhere."},{"q":"Why include an example in your prompt?","options":["It makes the prompt shorter","Examples are required","It shows the model the format and tone you want","It hides your request"],"answer":2,"explain":"Examples are a fast way to communicate style and structure."}],"suggestedDays":[{"day":4,"track":"common","reason":""},{"day":18,"track":"apps","reason":""}],"tracks":["common"],"topics":["prompting"],"tags":["prompting","docs","clarity","examples"],"level":"beginner","estMinutes":50}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-prompt-engineering');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-prompt-engineering', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-prompt-engineering') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-prompt-engineering');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-anthropic-courses', 'link', 'https://github.com/anthropics/courses', 'https://github.com/anthropics/courses', NULL, 'Anthropic''s educational courses', 'Anthropic', NULL, NULL, NULL, '["apps"]', '["apis","prompting"]', 'intermediate', 'en', '["ru","en"]', '[{"day":18,"track":"apps"}]', 'published', 'not_applicable', 'ready', 0, 10, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-anthropic-courses', 'ru', 'ready', '{"title":"Курсы Anthropic: API и промптинг на практике","hook":"Бесплатные интерактивные курсы от Anthropic на GitHub: от первого запроса к API до инструментов и оценки промптов.","summary":"Это репозиторий на GitHub, где Anthropic собрала несколько обучающих курсов. Среди них — основы работы с Claude API, интерактивный учебник по промпт-инжинирингу, промптинг на реальных задачах, оценка качества промптов и использование инструментов (tool use). Курсы сделаны в виде Jupyter-ноутбуков: это документы, где текст объяснений чередуется с кусочками кода, которые можно запускать.\n\nВсё на английском. Читать можно прямо на GitHub через переводчик в браузере, а запускать — у себя на компьютере. Для запуска нужен API-ключ Anthropic, а для него — аккаунт в консоли и пополненный баланс. Из России и некоторых других регионов с этим могут быть сложности (доступ к сервису, оплата российской картой), так что разберись заранее. Если ключа пока нет, всё равно читай: идеи и примеры полезны сами по себе.\n\nЭто не на один день. Сегодня начни с курса по основам API: поймёшь, как твоё будущее приложение будет общаться с моделью.","takeaways":["API — способ, которым программа обращается к модели: отправляет запрос и получает ответ.","API-ключ — секрет: его нельзя публиковать в коде или на GitHub, только в переменных окружения.","Курс по основам API показывает устройство запроса: модель, сообщения, системный промпт, ограничение длины ответа.","Промпты можно и нужно оценивать системно, а не «на глаз».","Tool use позволяет модели вызывать функции твоего приложения."],"steps":[{"title":"Открой репозиторий и выбери курс","detail":"Прочитай README через переводчик. Начни с курса по основам API."},{"title":"Разберись с ключом","detail":"Если есть доступ к консоли Anthropic, создай API-ключ. Сохрани его в файле .env или .dev.vars, который не попадает в Git."},{"title":"Запусти первый ноутбук с агентом","detail":"Попроси Claude Code: «Склонируй репозиторий anthropics/courses, установи зависимости и помоги запустить первый ноутбук курса по API. Ключ возьми из переменной окружения»."},{"title":"Сделай свой первый запрос","detail":"Измени пример: поменяй вопрос, добавь системный промпт на русском. Посмотри, как меняется ответ."},{"title":"Если ключа нет","detail":"Пройди уроки как чтение и попроси Claude объяснить каждый пример кода построчно. К запуску вернёшься позже."}],"exercise":{"title":"Мой первый запрос к Claude API","goal":"Отправить запрос к модели из кода и получить ответ — или подробно разобрать пример, если ключа пока нет.","instructions":["Пройди первые уроки курса по основам API.","С ключом: напиши маленький скрипт, который отправляет вопрос с системным промптом на русском и печатает ответ.","Без ключа: возьми пример кода из курса и подпиши комментарием каждую строку своими словами.","Проверь, что ключ нигде не попал в файлы, отслеживаемые Git.","Сохрани скрипт или разобранный пример."],"proof":"file","estMinutes":60},"quiz":[{"q":"Где правильно хранить API-ключ?","options":["Прямо в коде, чтобы не потерять","В публичном репозитории на GitHub","В переменных окружения или файле, исключённом из Git","В описании Telegram-канала"],"answer":2,"explain":"Ключ — это доступ к твоему балансу; его утечка может стоить денег."},{"q":"Что такое Jupyter-ноутбук?","options":["Документ, где объяснения чередуются с запускаемым кодом","Модель ноутбука для программистов","Сайт с видеоуроками","Формат видео"],"answer":0,"explain":"Ноутбуки удобны для обучения: можно читать и сразу запускать примеры."},{"q":"Что даёт модели tool use?","options":["Ускоряет интернет","Возможность вызывать функции твоего приложения","Бесплатный доступ к API","Перевод на русский"],"answer":1,"explain":"Модель решает, какую функцию вызвать и с какими параметрами, а твой код её выполняет."}],"suggestedDays":[{"day":18,"track":"apps","reason":""}],"tracks":["apps"],"topics":["apis","prompting"],"tags":["api","курсы","jupyter","промптинг","api-ключ"],"level":"intermediate","estMinutes":90}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-anthropic-courses');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-anthropic-courses', 'en', 'ready', '{"title":"Anthropic''s courses: API fundamentals and prompting, hands-on","hook":"Free, notebook-based courses that teach you to call Claude from code and write prompts that hold up.","summary":"This GitHub repository holds Anthropic''s educational courses, built as Jupyter notebooks you can run. The set includes an API fundamentals course (getting a key, sending messages, choosing models and parameters), an interactive prompt engineering tutorial, a course on real-world prompting, one on evaluating prompts, and one on tool use.\n\nThe repository suggests taking them in order, starting with the API fundamentals. That is the one that matters for your app this week: it shows how your code sends a message to Claude and reads the reply.\n\nRunning the notebooks needs an API key, which is a paid account. If you do not have one, you can still read the notebooks on GitHub, and your app should show an ''AI not configured'' message with a sensible fallback instead of crashing. Today, work through the first parts of API fundamentals.","takeaways":["Your app talks to Claude by sending a list of messages and receiving a reply.","Parameters such as the model and the maximum length of the reply shape what you get back.","API keys are secrets: keep them in environment variables, never in your code or repository.","Take the courses in order; API fundamentals comes first."],"steps":[{"title":"Open the repository and read the README","detail":"Note the list of courses and the suggested order."},{"title":"Read API fundamentals on GitHub","detail":"Even without running anything, read the first notebooks to see how a request is built."},{"title":"Set up your key safely (optional)","detail":"If you have an API key, ask Claude Code to help you store it in an environment variable file that is ignored by git."},{"title":"Add one AI call to your app","detail":"Ask Claude Code to add a single endpoint that sends a prompt to Claude and returns the reply, with a clear fallback message when no key is set."}],"exercise":{"title":"My app''s first AI call","goal":"Add one working AI-powered feature to your app, with a safe fallback.","instructions":["Pick a tiny AI feature for your app (for example: ''suggest a title for my note'').","With Claude Code, implement it using what you learned in API fundamentals.","Make sure the app shows a friendly ''AI not configured'' message if no API key is set.","Confirm your key is not committed to git, then share a screenshot of the feature working or of the fallback."],"proof":"file","estMinutes":75},"quiz":[{"q":"Which course does the repository suggest starting with?","options":["Tool use","API fundamentals","Prompt evaluations","Any order works"],"answer":1,"explain":"API fundamentals sets up everything the others build on."},{"q":"Where should your API key live?","options":["Hard-coded in your app","In your README","In a public GitHub issue","In an environment variable or secrets file that is not committed"],"answer":3,"explain":"Keys in a repository can be found and abused."},{"q":"What should your app do if no API key is configured?","options":["Crash with an error","Show a clear ''AI not configured'' state and a fallback","Silently do nothing","Ask users for their own password"],"answer":1,"explain":"A graceful fallback keeps the app usable and demoable."}],"suggestedDays":[{"day":18,"track":"apps","reason":""}],"tracks":["apps"],"topics":["apis","prompting"],"tags":["api","courses","notebooks","secrets"],"level":"intermediate","estMinutes":120}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-anthropic-courses');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-anthropic-courses', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-anthropic-courses') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-anthropic-courses');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-remotion-fundamentals', 'link', 'https://www.remotion.dev/docs/the-fundamentals', 'https://remotion.dev/docs/the-fundamentals', NULL, 'Remotion: The fundamentals', 'Remotion', NULL, NULL, NULL, '["video"]', '["remotion","motion-graphics"]', 'beginner', 'en', '["ru","en"]', '[{"day":18,"track":"video"}]', 'published', 'not_applicable', 'ready', 0, 9, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-remotion-fundamentals', 'ru', 'ready', '{"title":"Remotion: основы, без которых не собрать ролик","hook":"Официальный раздел документации Remotion о базовых понятиях. Прочитав его, ты будешь понимать код, который пишет для тебя агент.","summary":"Remotion — библиотека для создания видео на React. Раздел «The fundamentals» объясняет её основу: композиция (Composition) — это видео с заданными размером, частотой кадров и длительностью; хук useCurrentFrame() говорит компоненту, какой сейчас кадр; а всё, что ты видишь на экране, вычисляется из номера кадра. Там же рассказано о вспомогательных инструментах: interpolate() для плавного изменения значений, spring() для «пружинистых» анимаций, Sequence для размещения элементов во времени.\n\nДокументация на английском, читай через переводчик в браузере, а примеры кода копируй без перевода. Не пытайся выучить всё наизусть: агент напишет код сам. Тебе нужно понимать, что за чем стоит, чтобы точно ставить задачу и находить ошибки.\n\nДля справки: Remotion бесплатен для частных лиц и небольших команд, а компаниям крупнее определённого размера нужна платная лицензия. Подробности — на их сайте.","takeaways":["Композиция задаёт параметры видео: ширину, высоту, fps и длительность в кадрах.","useCurrentFrame() возвращает номер текущего кадра; от него зависит всё на экране.","interpolate() превращает номер кадра в плавно меняющееся значение — например, прозрачность от 0 до 1.","Sequence позволяет показать элемент с определённого кадра и на определённое время.","Remotion Studio показывает предпросмотр в браузере, а рендер создаёт готовый видеофайл."],"steps":[{"title":"Прочитай раздел через переводчик","detail":"Выпиши себе пять понятий: Composition, useCurrentFrame, useVideoConfig, interpolate, Sequence — с объяснением в одну строку."},{"title":"Открой свой проект Remotion","detail":"Если его нет, попроси Claude Code создать новый проект и запустить Studio."},{"title":"Попроси агента объяснить код","detail":"Скажи: «Покажи, где в проекте Composition, useCurrentFrame и interpolate, и объясни каждый кусок простыми словами»."},{"title":"Собери сцену из трёх частей","detail":"Попроси агента сделать видео из трёх последовательных сцен через Sequence: заголовок, основной текст, финальная надпись."},{"title":"Поменяй тайминг сам","detail":"Найди в коде числа кадров и поменяй одно, например продлив вторую сцену. Посмотри в Studio, что изменилось."}],"exercise":{"title":"Ролик из трёх сцен","goal":"Собрать видео из трёх сцен и понимать, какие строки кода за что отвечают.","instructions":["Попроси агента сделать видео на 10–15 секунд из трёх сцен с переходами.","Сам поменяй в коде хотя бы одно значение тайминга и одно значение анимации.","Отрендери MP4.","Напиши 3–4 предложения: какие функции Remotion использованы и что делает каждая."],"proof":"file","estMinutes":60},"quiz":[{"q":"Что возвращает useCurrentFrame()?","options":["Номер текущего кадра","Длительность видео в секундах","Название композиции","Путь к готовому файлу"],"answer":0,"explain":"Номер кадра — основа: от него вычисляются все анимации."},{"q":"Для чего нужен interpolate()?","options":["Для загрузки шрифтов","Для рендера в MP4","Для записи звука","Чтобы превратить номер кадра в плавно меняющееся значение"],"answer":3,"explain":"Например, кадры 0–30 превращаются в прозрачность от 0 до 1."},{"q":"Что делает Sequence?","options":["Сортирует файлы в проекте","Показывает элемент начиная с заданного кадра и на заданное время","Ускоряет рендер","Добавляет музыку"],"answer":1,"explain":"Sequence позволяет раскладывать элементы по таймлайну."}],"suggestedDays":[{"day":18,"track":"video","reason":""}],"tracks":["video"],"topics":["remotion","motion-graphics"],"tags":["remotion","react","анимация","документация"],"level":"beginner","estMinutes":75}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-remotion-fundamentals');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-remotion-fundamentals', 'en', 'ready', '{"title":"Remotion fundamentals: compositions, frames and animation","hook":"The official guide to the handful of ideas that every Remotion video is built from.","summary":"This section of the Remotion docs explains the core concepts in a short series of pages. A composition is a video definition: a component plus its width, height, frames per second and duration. Inside it, a hook gives you the current frame, and you calculate what to show from that number. Helpers such as interpolate turn a frame range into a value range (for example, opacity going from 0 to 1 over the first 30 frames), and Sequence lets you place parts of the video at different times.\n\nThe docs also show how to preview your video in the Remotion Studio in your browser and how to render it to an MP4 file.\n\nYou do not need to read every page in the docs today. Read the fundamentals pages in order, and keep the rest of the docs as a reference you and your agent can come back to.","takeaways":["A composition defines the video: component, size, fps and length in frames.","The current frame is the single source of truth for animation.","interpolate maps frames to values such as position, opacity or scale.","Sequence shifts parts of the video in time so you can build scenes.","You preview in the browser and render to a real video file when ready."],"steps":[{"title":"Read the fundamentals pages in order","detail":"Stop after each page and say in one sentence what it taught."},{"title":"Open your Remotion project from the last lesson","detail":"Or ask Claude Code to create a fresh one if you do not have it."},{"title":"Find the concepts in your own code","detail":"Ask the agent to point out where the composition, the current frame and interpolate appear in your project."},{"title":"Add a second scene with Sequence","detail":"Ask it to add a second part that starts after your title card ends."},{"title":"Render to MP4","detail":"Ask how to render the composition to a video file and run it."}],"exercise":{"title":"A two-scene, 10-second video","goal":"Render a real MP4 that uses a composition, interpolate and Sequence.","instructions":["Plan two scenes of about 5 seconds each: a title, then a short message or fact.","Build them with Claude Code in your Remotion project, using Sequence to place the second scene.","Make at least one property animate with interpolate (fade, slide or scale).","Render to MP4 and upload the file."],"proof":"file","estMinutes":75},"quiz":[{"q":"What does a composition define?","options":["The component plus its size, fps and duration","Only the background colour","Your Remotion licence","The music track only"],"answer":0,"explain":"A composition is the full definition of one renderable video."},{"q":"What is interpolate used for?","options":["Downloading fonts","Uploading to YouTube","Mapping a range of frames to a range of values","Compressing video"],"answer":2,"explain":"For example, frames 0–30 to opacity 0–1."},{"q":"What does Sequence let you do?","options":["Shift a part of the video to start at a different time","Sort files alphabetically","Change the video resolution","Record your screen"],"answer":0,"explain":"Sequence places children on the timeline."},{"q":"At 30 fps, how many frames is a 10-second video?","options":["30","100","300","3000"],"answer":2,"explain":"10 seconds times 30 frames per second is 300 frames."}],"suggestedDays":[{"day":18,"track":"video","reason":""}],"tracks":["video"],"topics":["remotion","motion-graphics"],"tags":["remotion","docs","animation","rendering"],"level":"beginner","estMinutes":105}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-remotion-fundamentals');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-remotion-fundamentals', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-remotion-fundamentals') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-remotion-fundamentals');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-manim-docs', 'link', 'https://docs.manim.community/en/stable/', 'https://docs.manim.community/en/stable', NULL, 'Manim Community documentation', 'Manim Community', NULL, NULL, NULL, '["video"]', '["motion-graphics","python"]', 'intermediate', 'en', '["ru","en"]', '[{"day":25,"track":"video"}]', 'published', 'not_applicable', 'ready', 0, 8, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-manim-docs', 'ru', 'ready', '{"title":"Документация Manim Community: установка и первая сцена","hook":"Официальная документация Manim Community — главный справочник, когда делаешь объясняющие анимации на Python вместе с агентом.","summary":"Это документация Manim Community Edition — версии Manim, которую поддерживает сообщество. Тут есть инструкции по установке, быстрый старт (Quickstart), обучающие примеры и подробный справочник по всем объектам и анимациям. Особенно полезна галерея примеров: короткие сцены с готовым кодом и видео результата.\n\nДокументация большая и на английском. Читай через переводчик в браузере, код копируй как есть. Сегодня сфокусируйся на двух вещах: установке и Quickstart. Справочник и галерею держи под рукой, когда будешь просить агента о новой анимации: можно найти похожий пример и сказать «сделай как здесь, но…».\n\nУчти, что многие примеры в интернете написаны для другой версии — ManimGL Гранта Сандерсона, и код между версиями не всегда совместим. Если агент или туториал выдаёт странные ошибки, первым делом проверь, для какой версии код.","takeaways":["Сцена в Manim — это класс, у которого в методе construct() описано, что происходит.","Для работы нужны Python и ffmpeg; LaTeX нужен только для формул.","Рендер в низком качестве (-ql) быстрее — им удобно проверять черновики.","Галерея примеров — лучший источник идей и готовых кусков кода.","Код для ManimGL и Manim Community отличается — следи за версией."],"steps":[{"title":"Пройди установку с агентом","detail":"Открой раздел Installation через переводчик и попроси Claude Code: «Установи Manim Community по официальной инструкции для моей системы и проверь ffmpeg»."},{"title":"Повтори Quickstart","detail":"Сделай пример из быстрого старта: круг, который появляется и превращается в квадрат. Запусти рендер с флагами для превью и низкого качества."},{"title":"Полистай галерею","detail":"Найди 2–3 примера, которые тебе нравятся. Скопируй ссылки — они станут образцами для агента."},{"title":"Сделай свою версию примера","detail":"Попроси агента: «Возьми этот пример из галереи и адаптируй: подписи на русском, мои цвета, длительность около 10 секунд»."}],"exercise":{"title":"Своя сцена по мотивам галереи","goal":"Установить Manim и сделать собственную анимацию на основе примера из документации.","instructions":["Установи Manim Community и отрендери пример из Quickstart.","Выбери пример из галереи.","С помощью агента адаптируй его под свою тему с русскими подписями.","Сохрани видео и ссылку на исходный пример."],"proof":"file","estMinutes":70},"quiz":[{"q":"Где в сцене Manim описывается анимация?","options":["В файле README","В методе construct() класса сцены","В настройках ffmpeg","В браузере"],"answer":1,"explain":"Всё, что показывается и анимируется, описывается внутри construct()."},{"q":"Зачем рендерить в низком качестве?","options":["Так видео лучше выглядит","Это обязательно для публикации","Так быстрее проверять черновики","Так меньше ошибок в коде"],"answer":2,"explain":"Финальный рендер в высоком качестве делаешь, когда всё отлажено."},{"q":"Почему код из туториала может не работать в Manim Community?","options":["Он может быть написан для другой версии — ManimGL","Manim не работает на русском","Нужен платный аккаунт","Документация устарела полностью"],"answer":0,"explain":"У версий разные API, поэтому код не всегда переносится один в один."}],"suggestedDays":[{"day":25,"track":"video","reason":""}],"tracks":["video"],"topics":["motion-graphics","python"],"tags":["manim","python","анимация","документация"],"level":"intermediate","estMinutes":80}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-manim-docs');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-manim-docs', 'en', 'ready', '{"title":"Manim Community docs: installation and quickstart","hook":"The official home for Manim Community, with a quickstart that gets your first animation rendered.","summary":"The Manim Community documentation covers installing Manim, a quickstart tutorial, deeper tutorials and guides, an example gallery and a full reference of every class. For a beginner the important parts are installation (Manim needs Python plus a few system tools, and LaTeX if you want to render maths formulas) and the quickstart, which builds a scene, renders it from the command line, and transforms one shape into another.\n\nThe example gallery is the best part to come back to: each example shows a short animation next to the code that made it, which makes it easy to point your agent at an example and ask for something similar.\n\nToday, read the installation page for your operating system and the quickstart. Skim the example gallery to collect ideas. Leave the reference section for when you need a specific class.","takeaways":["Manim scenes are Python classes with a construct method that lists what happens.","You render from the command line; low-quality preview renders are fast for iteration.","LaTeX is only needed if you want typeset maths formulas.","The example gallery pairs animations with code, which is perfect to show your agent."],"steps":[{"title":"Read installation for your system","detail":"Note what is required. Ask Claude Code to check what you already have installed."},{"title":"Follow the quickstart with your agent","detail":"Ask Claude Code to walk through the quickstart steps with you, explaining each command."},{"title":"Browse the example gallery","detail":"Pick two examples you like and save their links."},{"title":"Remix one example","detail":"Give Claude Code the example link and ask for a version with your own text and colours."}],"exercise":{"title":"Remix a gallery example","goal":"Render a Manim animation adapted from the official gallery.","instructions":["Pick one example from the Manim Community gallery.","Ask Claude Code to recreate it in your project, then change the text, colours and timing to fit a topic you care about.","Render it, first at low quality to iterate, then once at higher quality.","Upload the final video file."],"proof":"file","estMinutes":75},"quiz":[{"q":"Where do you describe what happens in a Manim scene?","options":["In a JSON settings file","In the video''s file name","In a separate spreadsheet","In the construct method of a Scene class"],"answer":3,"explain":"The construct method lists the animations in order."},{"q":"Why render at low quality while working?","options":["It looks better","It renders much faster, so you can iterate quickly","High quality is broken","It is required by the licence"],"answer":1,"explain":"Fast previews keep your feedback loop short."},{"q":"When do you need LaTeX installed?","options":["Always","Only on Windows","Never","Only to render typeset maths formulas"],"answer":3,"explain":"Plain text and shapes work without it."}],"suggestedDays":[{"day":25,"track":"video","reason":""}],"tracks":["video"],"topics":["motion-graphics","python"],"tags":["manim","docs","python","animation"],"level":"intermediate","estMinutes":105}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-manim-docs');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-manim-docs', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-manim-docs') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-manim-docs');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-ffmpeg-docs', 'link', 'https://ffmpeg.org/ffmpeg.html', 'https://ffmpeg.org/ffmpeg.html', NULL, 'ffmpeg Documentation', 'FFmpeg', NULL, NULL, NULL, '["video"]', '["ffmpeg"]', 'intermediate', 'en', '["ru","en"]', '[{"day":15,"track":"video"}]', 'published', 'not_applicable', 'ready', 0, 7, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-ffmpeg-docs', 'ru', 'ready', '{"title":"ffmpeg: швейцарский нож для видео","hook":"Официальная документация ffmpeg — инструмента, который режет, склеивает, сжимает и конвертирует видео одной командой. Агент знает его отлично, а ты научишься проверять.","summary":"ffmpeg — бесплатная программа для работы с видео и аудио из командной строки. Через неё работают огромное количество сервисов и редакторов, а в нашем видеотреке она нужна постоянно: обрезать ролик, склеить сцены, наложить звук, изменить размер под вертикальный формат, сжать файл для Telegram.\n\nОфициальная документация огромная, технически плотная и на английском. Читать её целиком не нужно. Сегодня разберись в базовой структуре команды (входной файл через -i, опции, выходной файл) и в нескольких ключевых опциях: -ss и -t для обрезки, -c для выбора кодека, -vf для видеофильтров вроде scale. Через переводчик в браузере это читается нормально, а команды копируй как есть.\n\nПрактичный подход: проси Claude Code собрать команду под задачу и объяснить каждый флаг, а потом сверяйся с документацией. Так ты быстро научишься читать чужие команды и не бояться их.","takeaways":["Базовая форма команды: ffmpeg -i вход [опции] выход.","-ss задаёт начало, -t длительность — так режут кусок видео.","-c copy копирует потоки без перекодирования: быстро и без потери качества, но не всегда точно по кадру.","-vf задаёт видеофильтры, например scale для изменения размера.","Всегда держи оригинал: работай с копиями и проверяй результат глазами."],"steps":[{"title":"Убедись, что ffmpeg установлен","detail":"Попроси Claude Code проверить ffmpeg -version и при необходимости установить его для твоей системы."},{"title":"Прочитай описание и основные опции","detail":"Через переводчик открой начало документации (Synopsis, Description) и найди в списке опций -i, -ss, -t, -c, -vf."},{"title":"Обрежь видео","detail":"Возьми любой свой ролик. Попроси агента: «Сделай команду, которая вырезает 10 секунд с 5-й секунды, и объясни каждый флаг». Сверь флаги с документацией."},{"title":"Сделай вертикальную версию","detail":"Попроси команду, которая превращает ролик в 1080×1920 для Reels или Shorts. Посмотри результат."},{"title":"Сожми файл","detail":"Попроси сжать видео до разумного размера для отправки в Telegram, сохранив читаемое качество. Сравни размеры файлов."}],"exercise":{"title":"Три команды ffmpeg, которые я понимаю","goal":"Выполнить три реальные операции с видео и уметь объяснить каждую команду.","instructions":["Возьми любое своё видео (можно ролик, отрендеренный в Remotion или Manim).","С помощью агента выполни: обрезку, изменение размера, сжатие.","Для каждой команды напиши, что делает каждый флаг, — сверяясь с документацией.","Пришли текст с тремя командами и объяснениями."],"proof":"text","estMinutes":45},"quiz":[{"q":"Как указывается входной файл в ffmpeg?","options":["Через -o","Через -v","Через -x","Через -i"],"answer":3,"explain":"-i input.mp4 — это входной файл."},{"q":"Что делает -c copy?","options":["Копирует потоки без перекодирования","Делает копию программы","Удаляет звук","Увеличивает качество"],"answer":0,"explain":"Без перекодирования быстро и без потерь, но обрезка может быть не точной по кадру."},{"q":"Как изменить размер видео?","options":["Через -t","Через фильтр scale в -vf","Через -ss","Переименовать файл"],"answer":1,"explain":"-vf scale=ширина:высота меняет размер кадра."}],"suggestedDays":[{"day":15,"track":"video","reason":""}],"tracks":["video"],"topics":["ffmpeg"],"tags":["ffmpeg","видео","командная строка","конвертация"],"level":"intermediate","estMinutes":60}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-ffmpeg-docs');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-ffmpeg-docs', 'en', 'ready', '{"title":"ffmpeg documentation: the core command-line tool","hook":"The Swiss army knife behind almost every video pipeline. Learn to read its manual so you can check what your agent writes.","summary":"ffmpeg is a free command-line tool that converts, cuts, resizes, combines and re-encodes audio and video. This page is its main manual. It is long and technical, but its structure is logical: a synopsis of the command shape, a description of how ffmpeg reads inputs, processes streams and writes outputs, a section on stream selection (which audio or video tracks end up in the output), and then a long list of options.\n\nThe key mental model: options apply to the file that comes right after them. An input file follows -i, and the last path on the line is the output. In between you can set things like a start time, a duration, a video filter to resize, or a codec.\n\nYou will rarely write ffmpeg commands by hand; your agent will. Today, read the synopsis, the detailed description and the stream selection section, so you can understand and sanity-check the commands it proposes.","takeaways":["An ffmpeg command is: options and inputs (after -i), then options and the output file.","Options apply to the next file on the command line, so order matters.","A file contains streams (video, audio, subtitles); you can choose which ones to keep.","Copying streams without re-encoding is fast and lossless; re-encoding lets you change format or quality.","Filters (such as scaling) transform frames between input and output."],"steps":[{"title":"Read the synopsis and description","detail":"Draw the flow: input file, demuxer, decoder, filters, encoder, muxer, output file."},{"title":"Read stream selection","detail":"In your own words, write how ffmpeg decides which streams go into the output by default."},{"title":"Ask your agent for three commands","detail":"Ask Claude Code for commands to: trim a clip to its first 10 seconds, resize it to 720 pixels wide, and extract the audio as MP3."},{"title":"Explain each command back","detail":"Before running, explain every part of each command using the docs. Ask the agent only when you are stuck."},{"title":"Run them on your own clip","detail":"Use the MP4 you rendered earlier in the track."}],"exercise":{"title":"Three ffmpeg transformations","goal":"Produce three new files from one video, and understand every flag you used.","instructions":["Take a video you made earlier in the track.","With your agent''s help, create: a 10-second trim, a 720px-wide version, and an MP3 of the audio (or a silent-audio note if it has none).","Write each command with a one-line explanation of every option.","Paste the commands and explanations into your journal."],"proof":"text","estMinutes":70},"quiz":[{"q":"In an ffmpeg command, what marks an input file?","options":["-o","--input-file only","-i","The first word"],"answer":2,"explain":"Inputs follow -i; the last path is usually the output."},{"q":"Why does the position of an option matter?","options":["Options apply to the next file listed","It does not","Options are sorted alphabetically","Only the first option is used"],"answer":0,"explain":"Placing an option before -i applies it to that input; before the output, to the output."},{"q":"What is the benefit of copying streams instead of re-encoding?","options":["It changes the resolution","It adds subtitles","It is fast and keeps the original quality","It shrinks the file a lot"],"answer":2,"explain":"Stream copy repackages data without decoding it."}],"suggestedDays":[{"day":15,"track":"video","reason":""}],"tracks":["video"],"topics":["ffmpeg"],"tags":["ffmpeg","cli","encoding","docs"],"level":"intermediate","estMinutes":110}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-ffmpeg-docs');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-ffmpeg-docs', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-ffmpeg-docs') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-ffmpeg-docs');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-pro-git-en', 'link', 'https://git-scm.com/book/en/v2', 'https://git-scm.com/book/en/v2', NULL, 'Pro Git book', 'Scott Chacon, Ben Straub', NULL, NULL, NULL, '["common"]', '["git"]', 'beginner', 'en', '["en"]', '[{"day":2,"track":"common"},{"day":6,"track":"common"}]', 'published', 'not_applicable', 'ready', 0, 6, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-pro-git-en', 'en', 'ready', '{"title":"Pro Git: chapters 1 and 2 for beginners","hook":"The free, official Git book. Two chapters give you everything you need to save and share your work safely.","summary":"Pro Git by Scott Chacon and Ben Straub is the standard free book on Git, the tool that records the history of your project so you can go back in time and share your work. The whole book is long; you do not need all of it.\n\nChapter 1, Getting Started, explains what version control is, why Git works the way it does, and how to install and configure it. Chapter 2, Git Basics, covers the everyday commands: creating a repository, checking status, staging and committing changes, viewing history, undoing things, and working with remotes such as GitHub.\n\nToday, read chapter 1 and the first sections of chapter 2 up to recording changes and viewing history. Your coding agent can run Git commands for you, but you need to understand what they do so you can tell whether your work is safe.","takeaways":["Git saves snapshots of your project called commits, so you can always go back.","Files move through three states: modified, staged, committed.","git status is the command to run whenever you are unsure what is going on.","A remote (like GitHub) is a copy of your repository somewhere else, used for backup and sharing."],"steps":[{"title":"Read chapter 1","detail":"Focus on what version control is and the three states of a file."},{"title":"Install and configure Git","detail":"Ask Claude Code to check whether Git is installed and help you set your name and email."},{"title":"Read chapter 2 up to viewing history","detail":"Try each command yourself in a practice folder as you read."},{"title":"Make three commits","detail":"Create a file, commit it, change it, commit again, then add a second file and commit."},{"title":"Read your history","detail":"Run git log and explain each line to yourself."}],"exercise":{"title":"My first repository with history","goal":"Create a Git repository with at least three meaningful commits and understand each one.","instructions":["In a new folder, initialise a Git repository.","Create a notes.md file about what you are learning and commit it.","Make at least two more changes, committing each with a clear message.","Paste the output of git log --oneline into your journal, with one sentence about what each commit contains."],"proof":"text","estMinutes":75},"quiz":[{"q":"What is a commit?","options":["A saved snapshot of your project at a point in time","A message to a teammate","A deleted file","A GitHub account"],"answer":0,"explain":"Commits are the building blocks of your project''s history."},{"q":"Which are the three main states of a file in Git?","options":["New, old, deleted","Open, closed, saved","Modified, staged, committed","Local, cloud, archived"],"answer":2,"explain":"Changes are made, staged for the next commit, then committed."},{"q":"Which command shows what is changed and what is staged right now?","options":["git status","git log","git push","git init"],"answer":0,"explain":"git status is your ''where am I'' command."},{"q":"What is a remote?","options":["A TV controller","A deleted branch","A copy of the repository hosted somewhere else, like GitHub","A type of commit"],"answer":2,"explain":"Remotes let you back up and share your work."}],"suggestedDays":[{"day":2,"track":"common","reason":""},{"day":6,"track":"common","reason":""}],"tracks":["common"],"topics":["git"],"tags":["git","version-control","book","basics"],"level":"beginner","estMinutes":120}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-pro-git-en');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-pro-git-en', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-pro-git-en') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-pro-git-en');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-pro-git-ru', 'link', 'https://git-scm.com/book/ru/v2', 'https://git-scm.com/book/ru/v2', NULL, 'Pro Git (на русском)', 'Scott Chacon, Ben Straub', NULL, NULL, NULL, '["common"]', '["git"]', 'beginner', 'ru', '["ru"]', '[{"day":2,"track":"common"},{"day":6,"track":"common"}]', 'published', 'not_applicable', 'ready', 0, 5, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-pro-git-ru', 'ru', 'ready', '{"title":"Pro Git на русском: книга, к которой возвращаются годами","hook":"Лучшая бесплатная книга о Git, официально переведённая на русский. Сегодня — только первые главы, остальное станет справочником.","summary":"Pro Git Скотта Шакона и Бена Страуба — классическая книга о Git, бесплатно доступная на официальном сайте git-scm.com, в том числе на русском языке. В ней объясняется всё: от того, что такое контроль версий, до ветвления, работы с удалёнными репозиториями и внутреннего устройства Git.\n\nЦеликом читать её сейчас не нужно — это сотни страниц. Сегодня прочитай первую главу («Введение») и вторую («Основы Git»): что такое Git, как он хранит данные, установка, первоначальная настройка, создание репозитория, коммиты, просмотр истории и отмена изменений. Третья глава про ветвление пригодится чуть позже, когда начнёшь работать через ветки и пулл-реквесты.\n\nПеревод сделан сообществом, поэтому местами встречаются непривычные термины. Если что-то непонятно, спроси Claude: «Объясни простыми словами, что значит вот этот абзац».","takeaways":["Git хранит снимки всего проекта, а не просто списки изменений.","У файла три состояния: изменён, подготовлен (staged, после git add) и зафиксирован (после git commit).","git status — главная команда, чтобы понять, что происходит.","git log показывает историю, а изменения можно отменить разными способами — осторожно.","Книга бесплатная и официальная — лучший справочник, когда нужна точность."],"steps":[{"title":"Прочитай главу 1","detail":"Особенно разделы про то, что такое Git и как он хранит данные. Это занимает около 20–30 минут."},{"title":"Прочитай главу 2 с терминалом","detail":"Повторяй каждую команду из книги в тестовой папке: git init, git status, git add, git commit, git log."},{"title":"Нарисуй три состояния файла","detail":"Рабочая папка → индекс (staging) → репозиторий. Подпиши, какие команды переводят файл между ними."},{"title":"Проверь себя с агентом","detail":"Попроси Claude Code: «Задай мне 5 практических задач по основам Git в этой папке и проверь, как я их выполнил»."}],"exercise":{"title":"Практикум по второй главе","goal":"Закрепить основные команды Git на практике, а не только в теории.","instructions":["В тестовом репозитории создай три файла и закоммить их в два разных коммита.","Измени файл, посмотри git status и git diff, потом закоммить.","Добавь файл .gitignore и проверь, что игнорируемый файл не попадает в git status.","Скопируй вывод git log --oneline и коротко опиши, что делал на каждом шаге."],"proof":"text","estMinutes":60},"quiz":[{"q":"Что делает команда git add?","options":["Создаёт новый репозиторий","Отправляет изменения на GitHub","Подготавливает изменения к следующему коммиту","Удаляет файл"],"answer":2,"explain":"git add переводит изменения в индекс — область подготовки к коммиту."},{"q":"Какая команда показывает текущее состояние файлов?","options":["git status","git push","git clone","git init"],"answer":0,"explain":"git status — команда, которую стоит запускать постоянно."},{"q":"Зачем нужен .gitignore?","options":["Чтобы удалить историю","Чтобы Git не отслеживал указанные файлы, например секреты и временные файлы","Чтобы ускорить коммиты","Чтобы скрыть репозиторий от других"],"answer":1,"explain":"Туда добавляют то, что не должно попадать в репозиторий: ключи, сборки, зависимости."}],"suggestedDays":[{"day":2,"track":"common","reason":""},{"day":6,"track":"common","reason":""}],"tracks":["common"],"topics":["git"],"tags":["git","книга","на русском","основы"],"level":"beginner","estMinutes":90}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-pro-git-ru');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-pro-git-ru', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-pro-git-ru') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-pro-git-ru');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-github-hello-world', 'link', 'https://docs.github.com/en/get-started/start-your-journey/hello-world', 'https://docs.github.com/en/get-started/start-your-journey/hello-world', NULL, 'Hello World — GitHub Docs', 'GitHub', NULL, NULL, NULL, '["common"]', '["git"]', 'beginner', 'en', '["ru","en"]', '[{"day":2,"track":"common"}]', 'published', 'not_applicable', 'ready', 0, 4, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-github-hello-world', 'ru', 'ready', '{"title":"Hello World на GitHub: репозиторий, ветка, пулл-реквест","hook":"Официальный пошаговый урок GitHub, который за полчаса проводит через главный рабочий цикл: ветка, коммит, пулл-реквест, слияние.","summary":"GitHub — сервис, где хранят Git-репозитории в интернете, совместно работают над кодом и показывают свои проекты. Этот урок из официальной документации GitHub проводит тебя через базовый цикл прямо в браузере: создать репозиторий, сделать ветку, внести изменения и закоммитить, открыть пулл-реквест (запрос на слияние изменений) и смержить его в основную ветку.\n\nИменно так работают команды разработчиков и так ты будешь работать с ИИ-агентом: агент делает изменения в отдельной ветке, а ты смотришь пулл-реквест и решаешь, принимать ли его. GitHub доступен из России, регистрация бесплатная, банковская карта для этого не нужна.\n\nУрок на английском, читай через переводчик в браузере. Если GitHub предлагает русский язык интерфейса документации, можно переключиться, но названия кнопок на сайте всё равно будут на английском — запоминай их в оригинале.","takeaways":["Репозиторий — папка проекта с историей изменений, хранящаяся на GitHub.","Ветка позволяет менять код, не трогая основную версию (main).","Пулл-реквест — предложение влить изменения из ветки в main, с обсуждением и просмотром разницы.","Слияние (merge) переносит изменения в основную ветку.","Этот же цикл ты будешь использовать для проверки работы агента."],"steps":[{"title":"Зарегистрируйся на GitHub","detail":"Если аккаунта нет, создай его. Используй ту же почту, что указал в git config."},{"title":"Пройди урок по шагам","detail":"Через переводчик в браузере. Создай репозиторий hello-world с README, как описано в уроке."},{"title":"Ветка, коммит, пулл-реквест","detail":"Создай ветку, отредактируй README (напиши пару строк о себе и своей цели на 66 дней), закоммить, открой пулл-реквест и смержи его."},{"title":"Повтори с агентом","detail":"Склонируй репозиторий к себе и попроси Claude Code: «Создай ветку, добавь файл plan.md с моим планом на неделю, закоммить и запушь». Потом открой пулл-реквест на GitHub."}],"exercise":{"title":"Мой первый смерженный пулл-реквест","goal":"Пройти полный цикл GitHub и получить публичную ссылку на результат.","instructions":["Создай репозиторий по уроку.","Сделай ветку, измени README и открой пулл-реквест с понятным описанием.","Смержи пулл-реквест.","Пришли ссылку на смерженный пулл-реквест."],"proof":"link","estMinutes":40},"quiz":[{"q":"Что такое пулл-реквест?","options":["Запрос на скачивание репозитория","Предложение влить изменения из ветки в основную","Сообщение об ошибке","Платная функция GitHub"],"answer":1,"explain":"В пулл-реквесте видно изменения, их обсуждают и потом сливают."},{"q":"Зачем работать в отдельной ветке?","options":["Чтобы менять код, не ломая основную версию","Так быстрее загружается сайт","Без ветки нельзя сделать коммит","Чтобы скрыть код от всех"],"answer":0,"explain":"Основная ветка остаётся рабочей, пока ты экспериментируешь."},{"q":"Как пулл-реквесты помогают работать с ИИ-агентом?","options":["Агент не умеет работать с GitHub","Пулл-реквесты автоматически исправляют ошибки агента","Можно спокойно просмотреть изменения агента перед тем, как принять их","Они нужны только для больших команд"],"answer":2,"explain":"Пулл-реквест — удобная точка проверки работы агента."}],"suggestedDays":[{"day":2,"track":"common","reason":""}],"tracks":["common"],"topics":["git"],"tags":["github","пулл-реквест","ветки","git"],"level":"beginner","estMinutes":45}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-github-hello-world');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-github-hello-world', 'en', 'ready', '{"title":"GitHub Hello World: repo, branch, pull request, merge","hook":"A short official tutorial that walks you through the core GitHub workflow in your browser.","summary":"This GitHub Docs tutorial teaches the basic GitHub workflow without needing the command line. You create a repository, make a branch so you can work without touching the main version, commit a change on that branch, open a pull request to propose the change, and merge it.\n\nThis is the same workflow your coding agent will use when it pushes work and opens pull requests for you. Doing it once by hand in the browser makes those steps feel familiar instead of mysterious.\n\nYou need a free GitHub account. The tutorial takes well under an hour, so do all of it today.","takeaways":["A repository holds your project and its history on GitHub.","A branch lets you work on a change without affecting the main version.","A pull request proposes your changes and shows exactly what is different.","Merging brings the approved changes into the main branch."],"steps":[{"title":"Create a GitHub account","detail":"If you do not have one, sign up for a free account."},{"title":"Follow the tutorial step by step","detail":"Create the repository, a branch, a commit and a pull request exactly as described."},{"title":"Read your own pull request","detail":"Look at the changed lines view and make sure you understand what is shown."},{"title":"Merge it","detail":"Merge the pull request and check that the main branch now contains your change."},{"title":"Connect it to yesterday''s work","detail":"Ask Claude Code to push the repository from your Git practice to a new GitHub repository."}],"exercise":{"title":"My first merged pull request","goal":"Complete the full branch-to-merge cycle and have a public repository to show for it.","instructions":["Complete the Hello World tutorial in your GitHub account.","Make sure the README describes who you are and that you are in a 66-day program.","Share the link to your merged pull request."],"proof":"link","estMinutes":45},"quiz":[{"q":"Why create a branch before making changes?","options":["Branches are faster to type","GitHub requires one branch per file","To delete the repository later","To work without affecting the main version"],"answer":3,"explain":"Branches isolate work in progress."},{"q":"What is a pull request?","options":["A request to download a repository","A proposal to merge changes from one branch into another","A bug report","A password reset"],"answer":1,"explain":"It shows the differences and lets them be reviewed and merged."},{"q":"After merging, where do your changes live?","options":["Only on your branch","Nowhere; they are discarded","In a separate repository","In the main branch"],"answer":3,"explain":"Merging brings the changes into the target branch."}],"suggestedDays":[{"day":2,"track":"common","reason":""}],"tracks":["common"],"topics":["git"],"tags":["github","pull-request","branching","tutorial"],"level":"beginner","estMinutes":50}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-github-hello-world');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-github-hello-world', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-github-hello-world') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-github-hello-world');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-cf-workers-start', 'link', 'https://developers.cloudflare.com/workers/get-started/guide/', 'https://developers.cloudflare.com/workers/get-started/guide', NULL, 'Cloudflare Workers: Get started (CLI)', 'Cloudflare', NULL, NULL, NULL, '["apps"]', '["deploy","web-basics"]', 'beginner', 'en', '["ru","en"]', '[{"day":11,"track":"common"}]', 'published', 'not_applicable', 'ready', 0, 3, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-cf-workers-start', 'ru', 'ready', '{"title":"Первый деплой на Cloudflare Workers","hook":"Официальный гайд, который за полчаса доводит твой код до живого адреса в интернете. Ссылку можно сразу отправить друзьям.","summary":"Деплой — это публикация твоего приложения в интернете, чтобы его можно было открыть по ссылке. Cloudflare Workers — платформа, где код запускается на серверах Cloudflare по всему миру, а у бесплатного плана щедрые лимиты, которых хватает для учебных и первых реальных проектов.\n\nГайд проводит через создание проекта командой npm create cloudflare@latest, локальный запуск через wrangler dev и публикацию через wrangler deploy. Wrangler — это консольная утилита Cloudflare. После деплоя приложение доступно по адресу на поддомене workers.dev.\n\nГайд на английском, читай через переводчик в браузере, а команды копируй как есть. Ещё проще — попроси Claude Code пройти гайд вместе с тобой. Регистрация в Cloudflare бесплатная, для бесплатного плана карта не нужна. Доступность сайтов на workers.dev из разных регионов, включая Россию, бывает нестабильной — проверь свою ссылку с телефона через мобильный интернет.","takeaways":["Деплой превращает код на твоём компьютере в сайт с адресом в интернете.","Wrangler — консольный инструмент Cloudflare: wrangler dev для локального запуска, wrangler deploy для публикации.","Сначала всегда проверяй локально, потом деплой.","Бесплатного плана Workers хватает для учебных и небольших проектов.","Секреты (ключи API) хранят не в коде, а в настройках Worker."],"steps":[{"title":"Зарегистрируйся в Cloudflare","detail":"Создай бесплатный аккаунт на cloudflare.com."},{"title":"Пройди гайд с агентом","detail":"Открой гайд через переводчик и попроси Claude Code: «Давай пройдём официальный гайд Cloudflare Workers Get started: создай проект и объясняй каждый шаг»."},{"title":"Запусти локально","detail":"Выполни wrangler dev (или npm run dev) и открой локальный адрес в браузере. Попроси агента поменять текст ответа и посмотри, как он обновился."},{"title":"Задеплой","detail":"Выполни wrangler deploy. При первом запуске Wrangler попросит войти в аккаунт через браузер. В конце ты получишь адрес на workers.dev."},{"title":"Проверь с телефона","detail":"Открой ссылку на телефоне через мобильный интернет. Если всё работает — отправь её другу."}],"exercise":{"title":"Мой сайт в интернете","goal":"Опубликовать в интернете свою первую страницу или простое приложение.","instructions":["Создай проект Workers по гайду (с помощью агента).","Попроси агента вывести твою страницу о себе вместо стандартного «Hello World».","Проверь локально, затем задеплой.","Пришли ссылку на рабочий адрес на workers.dev."],"proof":"link","estMinutes":50},"quiz":[{"q":"Что такое деплой?","options":["Удаление проекта","Публикация приложения в интернете","Создание коммита","Установка редактора кода"],"answer":1,"explain":"После деплоя приложение доступно по ссылке."},{"q":"Какая команда Wrangler публикует Worker?","options":["wrangler dev","wrangler init","wrangler login","wrangler deploy"],"answer":3,"explain":"wrangler dev запускает локально, wrangler deploy — публикует."},{"q":"Где правильно хранить API-ключи для Worker?","options":["В секретах настроек Worker, а не в коде","В коде на главной странице","В README","В названии проекта"],"answer":0,"explain":"Секреты задаются отдельно, например через wrangler secret, и не попадают в репозиторий."}],"suggestedDays":[{"day":11,"track":"common","reason":""}],"tracks":["common","apps"],"topics":["deploy","web-basics"],"tags":["деплой","cloudflare","workers","хостинг"],"level":"beginner","estMinutes":60}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-cf-workers-start');
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-cf-workers-start', 'en', 'ready', '{"title":"Cloudflare Workers: deploy your first app from the command line","hook":"Put real code on the internet in minutes, with a public URL you can send to anyone.","summary":"This Cloudflare guide shows how to create and deploy a Worker using the command line. A Worker is a small piece of code that runs on Cloudflare''s network and answers web requests. The guide uses a setup command to create a new project, Wrangler (Cloudflare''s command-line tool) to run it locally while you develop, and a deploy command to publish it to a free workers.dev address.\n\nYou need a free Cloudflare account and Node.js installed. Your coding agent can run every command for you; your job is to read what each command does, approve it, and check the result in the browser.\n\nIn the foundation phase, use it to deploy your first page. In the apps track, come back to it as the base for an app with its own API.","takeaways":["A Worker is code that runs on Cloudflare''s network and responds to web requests.","Wrangler is the command-line tool to create, run and deploy Workers.","Develop locally first, check it in the browser, then deploy.","Deploying gives you a public URL on workers.dev that anyone can open."],"steps":[{"title":"Create a Cloudflare account","detail":"A free account is enough."},{"title":"Read the guide once","detail":"Note the three phases: create the project, develop locally, deploy."},{"title":"Let your agent run the setup","detail":"In a new folder, ask Claude Code to follow the guide and create a Worker project. Approve each command after reading it."},{"title":"Change the response","detail":"Ask it to return a small HTML page about you instead of the default text, and check it locally."},{"title":"Deploy","detail":"Ask it to deploy. Log in to Cloudflare when prompted, then open the URL on your phone."}],"exercise":{"title":"My first public URL","goal":"Deploy a Worker that serves a page you designed, and share the link.","instructions":["Create and run a Worker locally following the guide, with your agent''s help.","Make it serve a simple HTML page with your name and what you are building.","Deploy it to workers.dev.","Share the public link."],"proof":"link","estMinutes":60},"quiz":[{"q":"What is Wrangler?","options":["A database","A code editor","Cloudflare''s command-line tool for Workers","A browser extension"],"answer":2,"explain":"You use Wrangler to develop and deploy Workers."},{"q":"Why run the Worker locally before deploying?","options":["To check changes quickly before making them public","Deploying is impossible otherwise","Local runs are faster on the internet","It is required for billing"],"answer":0,"explain":"Local development gives quick feedback with no risk."},{"q":"What do you get after deploying?","options":["A downloadable zip","An email attachment","A public URL anyone can visit","Nothing visible"],"answer":2,"explain":"Your Worker is live on a workers.dev address."}],"suggestedDays":[{"day":11,"track":"common","reason":""}],"tracks":["common","apps"],"topics":["deploy","web-basics"],"tags":["cloudflare","workers","deploy","wrangler"],"level":"beginner","estMinutes":80}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-cf-workers-start');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-cf-workers-start', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-cf-workers-start') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-cf-workers-start');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-mdn-getting-started', 'link', 'https://developer.mozilla.org/en-US/docs/Learn_web_development/Getting_started', 'https://developer.mozilla.org/en-US/docs/Learn_web_development/Getting_started', NULL, 'MDN: Getting started with web development', 'MDN', NULL, NULL, NULL, '["common"]', '["web-basics"]', 'beginner', 'en', '["en"]', '[{"day":5,"track":"common"}]', 'published', 'not_applicable', 'ready', 0, 2, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-mdn-getting-started', 'en', 'ready', '{"title":"MDN: Getting started with web development","hook":"The most trusted free guide to how websites are made, from the people who document the web.","summary":"MDN''s Getting started module is a beginner course on building for the web. It helps you set up the tools you need, then walks you through creating your first website: planning what it should contain, writing the content with HTML, styling it with CSS, adding a little interactivity with JavaScript, and publishing it. It also introduces how the web works and the standards behind it.\n\nYou will have an AI agent writing much of your code, but you still need to know what HTML, CSS and JavaScript each do, so you can describe what you want and spot when something is off. MDN is where you check those facts.\n\nToday, focus on the ''Your first website'' path: what each of the three languages is responsible for and how a page comes together. Skip deep detail; you can always come back.","takeaways":["HTML gives a page its structure and content.","CSS controls how it looks: colours, fonts, spacing and layout.","JavaScript adds behaviour and interactivity.","Planning the content and look before building makes the result much better.","MDN is the reference to check when your agent''s code or explanation seems off."],"steps":[{"title":"Read the module overview","detail":"Note which articles make up the ''Your first website'' path."},{"title":"Plan your page on paper","detail":"Decide the purpose, the content (a few headings and paragraphs), and two or three colours and fonts."},{"title":"Build the HTML with your agent","detail":"Ask Claude Code to create index.html with your planned content, and ask it to explain each tag it uses."},{"title":"Add CSS","detail":"Ask it to add a stylesheet that applies your colours and fonts. Change one value yourself and refresh."},{"title":"Add one small interaction","detail":"Ask for a tiny bit of JavaScript, such as a button that shows a hidden message."}],"exercise":{"title":"My first web page, three layers","goal":"Build a one-page site where you understand what the HTML, CSS and JavaScript each do.","instructions":["Use your plan to build index.html, a CSS file and a small JavaScript file with Claude Code.","Add a comment in each file, in your own words, explaining what that file is responsible for.","Open it in a browser on both a laptop-sized and a phone-sized window and fix anything that looks broken.","Upload a screenshot of the finished page."],"proof":"file","estMinutes":90},"quiz":[{"q":"Which language gives a web page its structure and content?","options":["CSS","HTML","JavaScript","Python"],"answer":1,"explain":"HTML marks up headings, paragraphs, images and links."},{"q":"You want to change the page''s colours and fonts. Which do you edit?","options":["HTML","JavaScript","The browser settings","CSS"],"answer":3,"explain":"CSS controls presentation."},{"q":"What is JavaScript mainly used for on a web page?","options":["Storing images","Adding behaviour and interactivity","Choosing the domain name","Defining headings"],"answer":1,"explain":"It responds to clicks, updates content and more."}],"suggestedDays":[{"day":5,"track":"common","reason":""}],"tracks":["common"],"topics":["web-basics"],"tags":["html","css","javascript","mdn"],"level":"beginner","estMinutes":120}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-mdn-getting-started');
INSERT INTO lib_events (resource_id, step, status, message) SELECT 'seed-mdn-getting-started', 'seed', 'info', 'seeded with hand-written materials' WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-mdn-getting-started') AND NOT EXISTS (SELECT 1 FROM lib_events WHERE resource_id = 'seed-mdn-getting-started');

INSERT OR IGNORE INTO lib_resources (id, source_type, url, canonical_url, external_id, title, author, description, duration_sec, thumbnail_url, tracks, topics, level, orig_lang, audience, suggested_days, status, transcript_state, ai_state, featured, sort_weight, created_by, published_at) VALUES ('seed-mdn-learn-ru', 'link', 'https://developer.mozilla.org/ru/docs/Learn', 'https://developer.mozilla.org/ru/docs/Learn', NULL, 'MDN: Изучение веб-разработки', 'MDN', NULL, NULL, NULL, '["common"]', '["web-basics"]', 'beginner', 'ru', '["ru"]', '[{"day":5,"track":"common"}]', 'published', 'not_applicable', 'ready', 0, 1, 'seed', 1793750400);
INSERT OR IGNORE INTO lib_materials (resource_id, lang, state, data, origin, model) SELECT 'seed-mdn-learn-ru', 'ru', 'ready', '{"title":"MDN: учимся вебу по главному справочнику","hook":"Учебный раздел MDN — самого надёжного источника знаний о вебе. Хотя код пишет агент, понимать HTML, CSS и JavaScript тебе всё равно нужно.","summary":"MDN Web Docs — справочник по веб-технологиям от Mozilla, которым пользуются разработчики всего мира. В разделе «Изучение веб-разработки» собраны учебные материалы для новичков: как устроен интернет, HTML для структуры страницы, CSS для оформления, JavaScript для интерактивности.\n\nЧасть материалов переведена на русский, но не всё: некоторые страницы открываются только на английском, а русские версии иногда отстают от оригинала. Если страницы нет на русском или она выглядит устаревшей, переключись на английский и включи переводчик в браузере.\n\nВесь раздел — это недели учёбы, и сегодня он не нужен целиком. Прочитай основы HTML и CSS: из чего состоит страница, что такое теги и как применять стили. Это даст тебе словарь, чтобы точно говорить агенту, что поменять, и понимать, что он сделал.","takeaways":["HTML задаёт структуру страницы: заголовки, абзацы, ссылки, картинки.","CSS отвечает за внешний вид: цвета, шрифты, отступы, расположение.","JavaScript добавляет интерактивность: реакцию на клики, изменения на странице.","Инструменты разработчика в браузере (F12) показывают код любой страницы — отличный способ учиться.","Точные слова («отступ», «заголовок h1», «flex») делают твои промпты к агенту гораздо точнее."],"steps":[{"title":"Открой учебный раздел","detail":"Найди материалы по основам HTML и CSS. Если русская страница кажется неполной, переключись на английский с переводчиком."},{"title":"Разбери свою страницу","detail":"Открой страницу, которую ты делал с агентом раньше, и найди в её коде теги и стили, о которых прочитал."},{"title":"Открой инструменты разработчика","detail":"Нажми F12 на любом сайте, выбери элемент и посмотри его HTML и CSS. Попробуй поменять цвет прямо в браузере."},{"title":"Дай агенту точную задачу","detail":"Используя новые слова, попроси Claude Code: например, «увеличь отступы между секциями, сделай заголовок h1 крупнее, выровняй карточки по сетке». Сравни с тем, как ты формулировал раньше."}],"exercise":{"title":"Улучшаю свою страницу точными словами","goal":"Применить базовые понятия HTML и CSS, чтобы осознанно улучшить свою страницу.","instructions":["Прочитай материалы по основам HTML и CSS.","Выпиши 10 терминов, которые теперь понимаешь (тег, атрибут, селектор, отступ и т. д.).","Дай агенту три точные правки для своей страницы, используя эти термины.","Сделай скриншоты «до» и «после»."],"proof":"file","estMinutes":60},"quiz":[{"q":"За что отвечает CSS?","options":["За структуру страницы","За хранение данных","За внешний вид: цвета, шрифты, отступы","За отправку писем"],"answer":2,"explain":"HTML — структура, CSS — оформление, JavaScript — поведение."},{"q":"Что делать, если нужной страницы MDN нет на русском?","options":["Открыть английскую версию и включить переводчик в браузере","Пропустить тему","Искать только на форумах","Учить английский перед продолжением"],"answer":0,"explain":"Английская версия полнее и актуальнее, а переводчик в браузере справляется хорошо."},{"q":"Зачем знать термины HTML и CSS, если код пишет агент?","options":["Агент не понимает русский","Без этого агент не запустится","Чтобы ставить точные задачи и понимать результат","Незачем"],"answer":2,"explain":"Точный словарь делает промпты конкретными и помогает проверять работу агента."}],"suggestedDays":[{"day":5,"track":"common","reason":""}],"tracks":["common"],"topics":["web-basics"],"tags":["html","css","веб-разработка","на русском"],"level":"beginner","estMinutes":75}', 'fixture', NULL WHERE EXISTS (SELECT 1 FROM lib_resources WHERE id = 'seed-mdn-learn-ru');
